return ['x-generator'=>'GlotPress/4.0.3','translation-revision-date'=>'2026-01-13 10:49:59+0000','plural-forms'=>'nplurals=3; plural=(n == 1) ? 0 : ((n % 10 >= 2 && n % 10 <= 4 && (n % 100 < 12 || n % 100 > 14)) ? 1 : 2);','project-id-version'=>'Plugins - Customer Reviews for WooCommerce - Stable (latest release)','language'=>'pl','messages'=>['Reviewer Type'=>'Rodzaj recenzenta','Refurbished'=>'Odnowiony','Used'=>'Używany','New'=>'Nowy','Not specified'=>'Nie określono','Use the condition attribute to describe condition (new, used or refurbished) of products.'=>'Użyj atrybutu „stan”, aby opisać stan produktów (nowe, używane lub odnowione).','Condition attribute for Google Shopping'=>'Atrybut stanu dla Google Shopping','Product Condition'=>'Stan produktu','Add a condition attribute to WooCommerce products (on \'General\' tab). The condition attribute refers to condition of products you are selling. It is an optional field for new products but required for used and refurbished products.'=>'Dodaj atrybut stanu do produktów WooCommerce (w zakładce „Ogólne”). Atrybut stanu odnosi się do stanu sprzedawanych produktów. Jest to pole opcjonalne w przypadku nowych produktów, ale wymagane w przypadku produktów używanych i odnowionych.','Condition'=>'Stan','Revenue attributed to purchases influenced by product recommendations shown on aggregated review forms.'=>'Przychody przypisane zakupom, na które wpływ miały rekomendacje produktów wyświetlane w zbiorczych formularzach recenzji.','Sales'=>'Sprzedaż','%1$s parameter accepts %2$s or %3$s and controls if %4$s structured data should be created for search engines. To comply with schema markup guidelines, this parameter takes effect only when the shortcode displays reviews for a single product, that is, when parameter %5$s is %3$s and parameter %6$s is set to either %7$s or a single product ID.'=>'Parametr %1$s akceptuje wartości %2$s lub %3$s i określa, czy dla wyszukiwarek mają być generowane dane strukturalne %4$s. Zgodnie z wytycznymi dotyczącymi znaczników schematu parametr ten działa tylko wtedy, gdy shortcode wyświetla recenzje dla pojedynczego produktu, czyli gdy parametr %5$s ma wartość %3$s, a parametr %6$s jest ustawiony na %7$s lub na pojedynczy identyfikator produktu.','Add JSON-LD structured data for product reviews on WooCommerce product pages to help search engines better understand and display your review content. Enable this only if your theme, WooCommerce, or SEO plugins are not already generating review schema, to avoid duplicate markup.'=>'Dodaj dane strukturalne JSON-LD dla recenzji produktów na stronach produktów WooCommerce, aby pomóc wyszukiwarkom lepiej zrozumieć i wyświetlać treści recenzji. Włącz to tylko wtedy, gdy twój motyw, WooCommerce lub wtyczki SEO nie generują już schematu recenzji, aby uniknąć duplikowania znaczników.','Review Schema Markup'=>'Znaczniki schematu recenzji','Coupon code that was sent to the reviewer after they submitted this review'=>'Kupon rabatowy, który został wysłany autorowi recenzji po jej przesłaniu','%1$s parameter accepts %2$s or %3$s and controls if %4$s structured data should be created for search engines. To comply with schema markup guidelines, this parameter takes effect only when the shortcode displays reviews for a single product, that is, when parameter %5$s is %2$s, parameter %6$s is %3$s, and parameter %7$s is set to either %8$s or a single product ID.'=>'Parametr %1$s akceptuje %2$s lub %3$s i określa, czy dane strukturalne %4$s mają być generowane dla wyszukiwarek. Aby dostosować się do wytycznych dotyczących oznaczenia schematu, ten parametr działa tylko wtedy, gdy shortcode wyświetla recenzje dla pojedynczego produktu, czyli gdy parametr %5$s to %2$s, parametr %6$s to %3$s, a parametr %7$s jest ustawiony na %8$s lub na pojedynczy identyfikator produktu.','Another shop review. Note that the product_id is still -1 and product_sku is blank. Customer service is good!'=>'Kolejna recenzja sklepu. Zwróć uwagę, że product_id nadal wynosi -1, a pole product_sku jest puste. Obsługa klienta jest na dobrym poziomie!','Review Title'=>'Tytuł recenzji','Line %1$d >> Error: A matching review with ID %2$d could not be found.'=>'Linia %1$d >> Błąd: Nie znaleziono pasującej recenzji o identyfikatorze %2$d.','Line %1$d >> Error: Duplicate review or reply to review.'=>'Linia %1$d >> Błąd: Zduplikowana recenzja lub odpowiedź na recenzję.','Line %1$d >> Error: product SKU %2$d refers to a product variation. Use the parent product SKU instead.'=>'Linia %1$d >> Błąd: SKU produktu %2$d odnosi się do wariantu produktu. Użyj SKU produktu nadrzędnego.','Keep the column \'order_id\' blank unless you are importing a file created with the export utility of this plugin'=>'Pozostaw kolumnę \'order_id\' pustą, chyba że importujesz plik utworzony za pomocą narzędzia eksportu tej wtyczki.','Use -1 as a product ID to import general shop reviews that are not related to any particular product'=>'Użyj -1 jako identyfikatora produktu do importowania ogólnych recenzji sklepu, które nie są powiązane z żadnym konkretnym produktem.','Add your reviews and replies to reviews to the template and save the file (if using MS Excel, choose CSV UTF-8 format)'=>'Dodaj swoje recenzje i odpowiedzi do szablonu i zapisz plik (jeśli używasz programu MS Excel, wybierz format CSV UTF-8).','Get the CSV template for entering your reviews and replies to reviews'=>'Pobierz szablon CSV do wprowadzania recenzji i odpowiedzi na recenzje.','You can use this tool to import reviews and replies to reviews in three steps:'=>'Możesz użyć tego narzędzia, aby zaimportować recenzje oraz odpowiedzi na recenzje w trzech krokach:','Line %1$d >> Error: no data for this Q & A.'=>'Linia %1$d >> Błąd: brak danych dla tej sekcji pytań i odpowiedzi.','Export failed: Could not read replies to reviews from the database.'=>'Eksport nie powiódł się: Nie można odczytać odpowiedzi na recenzje z bazy danych.','Export failed: Could not read reviews from the database.'=>'Eksport nie powiódł się: Nie można odczytać recenzji z bazy danych.','A utility to export reviews and replies to a CSV file.'=>'Narzędzie do eksportowania recenzji i odpowiedzi do pliku CSV.','%d review(s) and/or reply(s) successfully exported'=>'Pomyślnie wyeksportowano %d recenzji i/lub odpowiedzi.','%d duplicate reply(s) to review(s) skipped'=>'Pominięto %d zduplikowanych odpowiedzi na recenzje.','%d reply(s) to review(s) successfully uploaded'=>'Pomyślnie zaimportowano %d odpowiedzi do recenzji.','Store Manager'=>'Kierownik sklepu','This is a reply to the review with the id = 2. Sorry it did not meet your expectations — thanks for the feedback!'=>'To jest odpowiedź na recenzję o identyfikatorze 2. Przepraszamy, że nie spełniła twoich oczekiwań - dziękujemy za uwagi!','Line %1$d >> Error: product ID %2$d refers to a product variation. Use the parent product ID instead.'=>'Linia %1$d >> Błąd: identyfikator produktu %2$d odnosi się do wariantu produktu. Użyj identyfikatora produktu nadrzędnego.','Error: no products found for the XML Product Review Feed. Please check exclusion settings for products and product categories.'=>'Błąd: nie znaleziono produktów dla kanału XML recenzji produktów. Sprawdź ustawienia wykluczeń dla produktów i kategorii produktów.','Error: order ID is missing'=>'Błąd: brakuje identyfikatora zamówienia','Error: could not copy a link to an aggregated review form'=>'Błąd: nie można skopiować odnośnika do zagregowanego formularza recenzji','CR: a link to an aggregated review form was copied manually.'=>'CR: odnośnik do zagregowanego formularza recenzji został skopiowany ręcznie.','Error: a link to an aggregated review form cannot be copied because reviews(s) have already been collected with a CusRev mailer for this order.'=>'Błąd: nie można skopiować odnośnika do zagregowanego formularza opinii, ponieważ opinie zostały już zebrane za pomocą mailera CusRev dla tego zamówienia.','Error: links to aggregated review forms can be copied only with the self-hosted setting.'=>'Błąd: odnośniki do zagregowanych formularzy recenzji mogą być kopiowane tylko w przypadku ustawienia samodzielnego hostowania (self-hosted).','Link to the aggregated review form copied. Paste it where you need it.'=>'Skopiuj odnośnik do zagregowanego formularza recenzji. Wklej go tam, gdzie jest potrzebny.','Copied'=>'Skopiowano','Copying...'=>'Kopiowanie...','Link'=>'Odnośnik','Copy a link to an aggregated review form for this order.'=>'Skopiuj odnośnik do zagregowanego formularza recenzji dla tego zamówienia.','Test email could not be sent because settings for discounts are not saved; please save them on the <a href="%s">Review for Discount</a> page and then try again.'=>'Nie można wysłać wiadomości e-mail z testem, ponieważ ustawienia dotyczące rabatów nie zostały zapisane. Proszę je zapisać na stronie <a href="%s">Sprawdź rabaty</a>, a następnie spróbować ponownie.','Error: Both the Site key and the Secret key are required for reCAPTCHA to function properly'=>'Błąd: Do prawidłowego działania reCAPTCHA wymagany jest klucz witryny i klucz prywatny','This is the internal reference number for an answer'=>'To jest wewnętrzny numer referencyjny odpowiedzi','This is the internal reference number for a question'=>'To jest wewnętrzny numer referencyjny pytania','ID: %s'=>'Identyfikator: %s','Import Reviews'=>'Import recenzji','Line %1$d >> Error: A matching question with ID %2$d could not be found.'=>'Wiersz %1$d >> Błąd: Nie znaleziono pasującego pytania o identyfikatorze %2$d.','Line %1$d >> Error: Duplicate question or answer.'=>'Wiersz %1$d >> Błąd: Duplikat pytania lub odpowiedzi.','Line %1$d >> Error: products, posts or pages with ID = %2$d don\'t exist on this WordPress site.'=>'Wiersz %1$d >> Błąd: produkty, wpisy lub strony o identyfikatorze = %2$d nie istnieją w tej witrynie WordPress.','Line %1$d >> Error: products, posts or pages with ID = %2$d and products with SKU = %3$s don\'t exist on this WordPress site.'=>'Wiersz %1$d >> Błąd: produkty, wpisy lub strony o identyfikatorze %2$d i produkty o kodzie SKU %3$s nie istnieją w tej witrynie WordPress.','Line %1$d >> Error: product_id must be a positive number or \'-1\' for general Q & A about a shop.'=>'Wiersz %1$d >> Błąd: product_id musi być liczbą dodatnią lub „-1” w przypadku ogólnych pytań i odpowiedzi na temat sklepu.','Line %1$d >> Error: either product_id or product_sku must be provided.'=>'Wiersz %1$d >> Błąd: należy podać product_id lub product_sku.','Error: could not open the import file'=>'Błąd: nie można otworzyć pliku importu','Invalid or missing column headers detected in the CSV file. Refer to the Step 1 template for the correct format.'=>'W pliku CSV wykryto nieprawidłowe lub brakujące nagłówki kolumn. Zapoznaj się z szablonem kroku 1, aby uzyskać prawidłowy format.','Error details:'=>'Szczegóły błędu:','Step 3: Upload and import'=>'Krok 3: Prześlij i rozpocznij import','Step 2: Fill in the template'=>'Krok 2: Wypełnij szablon','Step 1: Download the template'=>'Krok 1: Pobierz szablon','Upload the completed template and run the import process'=>'Prześlij wypełniony szablon i uruchom proces importu','Upload and import'=>'Prześlij i zaimportuj','Alternatively, you can use page or post IDs if you want to import questions and answers for non-product pages'=>'Alternatywnie możesz użyć identyfikatorów stron lub wpisów, jeśli chcesz zaimportować pytania i odpowiedzi dla stron innych niż produkty','Make sure to enter valid product IDs that exist on your WooCommerce site'=>'Upewnij się, że wprowadzasz prawidłowe identyfikatory produktów, które istnieją na twojej witrynie internetowej WooCommerce','Add your questions and answers to the template and save the file (if using MS Excel, choose CSV UTF-8 format)'=>'Dodaj swoje pytania i odpowiedzi do szablonu i zapisz plik (jeśli używasz programu MS Excel, wybierz format CSV UTF-8)','Fill in the template'=>'Wypełnij szablon','Get the CSV template for entering your questions and answers'=>'Pobierz szablon CSV, w którym możesz wpisać swoje pytania i odpowiedzi','Download the template'=>'Pobierz szablon','You can use this tool to import questions and answers in three steps:'=>'Za pomocą tego narzędzia możesz importować pytania i odpowiedzi w trzech krokach:','Import Questions & Answers from CSV'=>'Importuj pytania i odpowiedzi z pliku CSV','Import Q & A'=>'Importuj pytania i odpowiedzi','Export failed: Could not open the file \'%s\' for writing.'=>'Eksport nie powiódł się: Nie można otworzyć pliku \'%s\' do zapisu.','Export failed: Could not read Q & A from the database.'=>'Eksport nie powiódł się: Nie można odczytać pytań i odpowiedzi z bazy danych.','%d question(s) and/or answer(s) successfully exported'=>'%d pytań i/lub odpowiedzi zostało pomyślnie wyeksportowanych','Export Questions and Answers to CSV'=>'Eksportuj pytania i odpowiedzi do pliku CSV','A utility to export questions and answers to a CSV file.'=>'Narzędzie umożliwiające eksportowanie pytań i odpowiedzi do pliku CSV.','A utility to export questions and answers to a CSV file. Use the Export button to start export of Questions and Answers. Use the Download button to download the last export.'=>'Narzędzie do eksportowania pytań i odpowiedzi do pliku CSV. Użyj przycisku Eksportuj, aby rozpocząć eksport pytań i odpowiedzi. Użyj przycisku Pobierz, aby pobrać ostatni eksport.','Export Q & A'=>'Eksport pytań i odpowiedzi','%d duplicate answer(s) skipped'=>'Pominięto %d duplikatów odpowiedzi','%d duplicate question(s) skipped'=>'Pominięto %d duplikatów pytań','%d answer(s) successfully uploaded'=>'Pomyślnie zaimportowano %d odpowiedzi.','%d question(s) successfully uploaded'=>'Pomyślnie zaimportowano %d pytań.','Another Store Manager'=>'Kolejny kierownik sklepu','To keep the best fit, we recommend washing in cold water and air drying, as this helps minimize any natural fabric shrinkage over time.'=>'Aby zachować najlepsze dopasowanie, zalecamy pranie w zimnej wodzie i suszenie na powietrzu, ponieważ pomaga to ograniczyć naturalne kurczenie się materiału z upływem czasu.','Sample Store Manager'=>'Przykładowy kierownik sklepu','The t-shirt is made from pre-shrunk cotton, so it holds its size well after washing.'=>'Koszulka jest wykonana z bawełny poddanej procesowi skurczenia, dzięki czemu dobrze zachowuje swój rozmiar po praniu.','Does this t-shirt shrink after washing?'=>'Czy ta koszulka kurczy się po praniu?','Test mode'=>'Tryb testowy','via CR (Test)'=>'przez CR (Test)','Aggregated review forms will be automatically deleted after the specified number of days, or kept indefinitely if set to 0.'=>'Zbiorcze formularze recenzji zostaną automatycznie usunięte po upływie określonej liczby dni lub zachowane na czas nieokreślony, jeśli zostanie ustawiona wartość 0.','Expiry Period'=>'Okres ważności','Oops! This review form isn’t available - it may have expired or the order has nothing to review.'=>'Ups! Ten formularz recenzji jest niedostępny - mógł wygasnąć lub zamówienie nie zawiera produktów do recenzji.','Reviews submitted via on-site review forms'=>'Recenzje przesłane za pośrednictwem formularzy recenzji na stronie','On-site review form'=>'Formularz recenzji na stronie','Reviews submitted via aggregated review forms'=>'Recenzje przesłane za pośrednictwem zbiorczych formularzy recenzji','Aggregated review form'=>'Zbiorczy formularz recenzji','I confirm that I will send review invitations only with consent of customers and agree to CusRev’s %1$sterms and conditions%2$s'=>'Potwierdzam, że będę wysyłał zaproszenia do wystawienia recenzji wyłącznie za zgodą klientów i akceptuję %1$swarunki korzystania%2$s CusRev','Gain greater exposure for your store through the CusRev platform, with cross-store product recommendations that help attract new customers'=>'Zwiększ rozpoznawalność swojego sklepu dzięki platformie CusRev, dzięki rekomendacjom produktów w różnych sklepach, które pomogą przyciągnąć nowych klientów','Increased store visibility through the CusRev platform and cross-store product recommendations'=>'Zwiększona widoczność sklepu dzięki platformie CusRev i rekomendacjom produktów w różnych sklepach','Aggregated review forms will be hosted by CusRev while on-site review forms will be hosted on your server'=>'Zbiorcze formularze recenzji będą hostowane przez CusRev, natomiast formularze recenzji na stronie będą hostowane na twoim serwerze','Use %1$s for collection and verification of reviews'=>'Użyj %1$s do zbierania i weryfikacji recenzji','No dependency on third-party review platforms'=>'Brak zależności od zewnętrznych platform recenzji','A self-hosted review system that is managed and run directly on your own WordPress website'=>'Samodzielnie hostowany system recenzji, który jest zarządzany i uruchamiany bezpośrednio na twojej własnej witrynie internetowej WordPress','An aggregated review form is a review form that supports collection of reviews for multiple products at the same time. On-site review forms are normally displayed on product pages. They can also be displayed in other places on your website using shortcodes.'=>'Zbiorczy formularz recenzji to formularz recenzji, który obsługuje zbieranie recenzji dla wielu produktów w tym samym czasie. Formularze recenzji na stronie są zazwyczaj wyświetlane na stronach produktów. Mogą być również wyświetlane w innych miejscach na twojej witrynie internetowej za pomocą krótkich kodów.','Aggregated review forms and on-site review forms will be hosted locally on your server'=>'Zbiorcze formularze recenzji i formularze recenzji na stronie będą hostowane lokalnie na twoim serwerze','Self-hosted'=>'Samodzielnie hostowane','XML Product Review Feed for Google Shopping is being generated in background - reviews %1$s to %2$s out of %3$s.'=>'Kanał recenzji produktów XML dla usługi Zakupy Google jest generowany w tle - liczba recenzji: %1$s do %2$s z %3$s.','Update progress'=>'Aktualizuj postęp','XML Product Feed for Google Shopping is being generated in background - products %1$s to %2$s out of %3$s.'=>'Kanał produktów XML dla usługi Zakupy Google jest generowany w tle - produkty od %1$s do %2$s z %3$s.','Due to regulatory restrictions, CusRev is unable to collect and verify reviews for prohibited categories of products (e.g., CBD or Kratom)'=>'Ze względu na ograniczenia regulacyjne CusRev nie jest w stanie zbierać i weryfikować opinii na temat zabronionych kategorii produktów (np. CBD lub Kratom)','CusRev uses AWS SES (Simple Email Service) for sending emails to ensure their excellent deliverability'=>'CusRev korzysta z AWS SES (Prosta usługa e-mail) do wysyłania wiadomości e-mail, aby zapewnić ich doskonałą dostarczalność','CusRev (Customer Reviews) is a service for businesses that offers a voluntary scheme for verification of reviews submitted by customers'=>'CusRev (Recenzje klientów) to usługa dla firm oferująca dobrowolny program weryfikacji opinii przesyłanych przez klientów','Close'=>'Zamknij','Line %1$d >> Error: product with ID = %2$d or SKU = %3$s doesn\'t exist in this WooCommerce store.'=>'Wiersz %1$d >> Błąd: produkt o identyfikatorze %2$d lub kodzie SKU %3$s nie istnieje w tym sklepie WooCommerce.','Line %1$d >> Error: could not find a product with SKU = %2$s.'=>'Wiersz %1$d >> Błąd: nie można znaleźć produktu o numerze SKU = %2$s.','This is a shop review. Note that the product_id is -1 and product_sku is blank. Customer service is good!'=>'To jest recenzja sklepu. Zwróć uwagę, że product_id to -1, a product_sku jest puste. Obsługa klienta jest dobra!','Error: a review reminder could not be sent using CusRev mailer. Please re-save options on the CusRev.com tab at the plugin\'s settings page.'=>'Błąd: przypomnienie o recenzji nie mogło zostać wysłane za pomocą poczty CusRev. Zapisz ponownie opcje na karcie CusRev.com na stronie ustawień wtyczki.','Use %1$s shortcode to display this badge on your site. If the shortcode includes %2$s argument, you can set it to %3$s or %4$s to display or hide border. If the shortcode includes %5$s argument, you can set it to a custom %6$s (in HEX format).'=>'Użyj %1$s krótkiego kodu, aby wyświetlić tę plakietkę na swojej stronie. Jeśli krótki kod zawiera %2$s argument, możesz ustawić go na %3$s lub %4$s, aby wyświetlić lub ukryć obramowanie. Jeśli krótki kod zawiera %5$s argument, możesz ustawić go na niestandardowy %6$s (w formacie HEX).','Since CusRev does not display copies of reviews, there are no restrictions on allowed categories of products'=>'Ponieważ CusRev nie wyświetla kopii recenzji, nie ma ograniczeń co do dozwolonych kategorii produktów','The plugin will use the standard \'wp_mail\' function for sending emails in WordPress'=>'Wtyczka będzie używać standardowej funkcji „wp_mail” do wysyłania wiadomości e-mail w WordPressie','A complete reviews collection solution hosted on your server'=>'Kompleksowe rozwiązanie do zbierania recenzji hostowane na twoim serwerze','Choose user roles...'=>'Wybierz role użytkownika...','Choose categories...'=>'Wybierz kategorie...','The reminder was not sent as scheduled, which may indicate an issue with WP Cron on this website. Try refreshing the page 2-3 times to see if the issue resolves. If the problem persists, contact your web hosting provider and request that WP Cron be enabled on your website.'=>'Przypomnienie nie zostało wysłane zgodnie z planem, co może wskazywać na problem z WP Cron na tej witrynie internetowej. Spróbuj odświeżyć stronę 2-3 razy, aby sprawdzić, czy problem ustąpi. Jeśli problem będzie się powtarzał, skontaktuj się z dostawcą hostingu i poproś o włączenie WP Cron na swojej witrynie internetowej.','The reminder is overdue'=>'Przypomnienie jest spóźnione','Recommendations'=>'Rekomendacje','The number of times customers clicked on your store\'s product recommendations shown on aggregated review forms.'=>'Liczba kliknięć klientów na rekomendacje produktów w twoim sklepie wyświetlane w formularzach zbiorczych opinii.','Clicks'=>'Kliknięcia','Product Recommendations on Review Forms'=>'Rekomendacje produktów w formularzach recenzji','The number of times your store\'s products were displayed as recommendations on aggregated review forms.'=>'Liczba wyświetleń produktów twojego sklepu jako rekomendacji w formularzach zbiorczych recenzji.','Views'=>'Wyświetlenia','This review was submitted in response to a review invitation sent for the order %s'=>'Ta recenzja została przesłana w odpowiedzi na zaproszenie do wystawienia recenzji wysłane dla zamówienia %s','Orders'=>'Zamówienia','Review reminders can be manually triggered from the WooCommerce Orders page by clicking the envelope button next to each order.'=>'Przypomnienia o recenzji można uruchomić ręcznie na stronie zamówień WooCommerce, klikając przycisk koperty obok każdego zamówienia.','Review reminders are sent automatically with a delay and parameters defined in the settings.'=>'Przypomnienia o recenzjach są wysyłane automatycznie z opóźnieniem i zgodnie z parametrami zdefiniowanymi w ustawieniach.','Review reminders are switched off. Enabling them can help you gather more authentic feedback from your customers about the products, services, and your store.'=>'Przypomnienia o recenzjach są wyłączone. Włączenie ich może pomóc Ci zebrać bardziej autentyczne opinie od klientów na temat produktów, usług i twojego sklepu.','Off'=>'Wyłącz','Review reminders are configured to invite customers to review their orders using aggregated review forms hosted on CusRev.com. These reviews are collected in "Test" mode, which means they will only be displayed on your website but not on CusRev.com. The "Test" mode is intended for setting up and testing the integration of the plugin with CusRev.com. You can adjust this configuration in the plugin settings.'=>'Przypomnienia o recenzjach są skonfigurowane tak, aby zapraszać klientów do recenzowania swoich zamówień za pomocą zagregowanych formularzy recenzji hostowanych na CusRev.com. Recenzje te są gromadzone w trybie "Test", co oznacza, że będą wyświetlane tylko na twojej stronie internetowej, ale nie na CusRev.com. Tryb "Test" jest przeznaczony do konfigurowania i testowania integracji wtyczki z CusRev.com. Możesz dostosować tę konfigurację w ustawieniach wtyczki.','Review reminders are configured to invite customers to review their orders using aggregated review forms hosted on CusRev.com. These reviews are collected in "Live" mode, meaning they will be publicly published both on CusRev.com and your website. You can adjust this configuration in the plugin settings.'=>'Przypomnienia o recenzjach są skonfigurowane tak, aby zapraszać klientów do przeglądania ich zamówień za pomocą zagregowanych formularzy recenzji hostowanych na CusRev.com. Te recenzje są zbierane w trybie „Na żywo”, co oznacza, że ​​będą publicznie publikowane zarówno na CusRev.com, jak i na twojej witrynie internetowej. Możesz dostosować tę konfigurację w ustawieniach wtyczki.','Review reminders are configured to invite customers to review their orders using aggregated review forms hosted locally on your website. This setup is ideal for meeting personal data protection requirements, as customer data does not leave your website. You can adjust this configuration in the plugin settings.'=>'Przypomnienia o recenzjach są skonfigurowane tak, aby zapraszać klientów do przeglądania ich zamówień za pomocą zagregowanych formularzy recenzji hostowanych lokalnie na twojej witrynie internetowej. Ta konfiguracja jest idealna do spełniania wymogów ochrony danych osobowych, ponieważ dane klientów nie opuszczają twojej witryny internetowej. Możesz dostosować tę konfigurację w ustawieniach wtyczki.','An error occurred while downloading a media file. Error code: %1$s. Error description: %2$s. Error data: %3$s. Product ID: %4$s. Parameters: %5$s.'=>'Wystąpił błąd podczas pobierania pliku multimedialnego. Kod błędu: %1$s. Opis błędu: %2$s. Dane błędu: %3$s. Identyfikator produktu: %4$s. Parametry: %5$s.','Media from review %s'=>'Media z recenzji %s','You must be logged in to ask a question'=>'Musisz być zalogowany, aby zadać pytanie','You must be logged in to answer a question'=>'Musisz być zalogowany, aby odpowiedzieć na pytanie','Add a checkbox for people to accept your Terms and Conditions, Privacy Policy, and any other legal agreements required in your jurisdiction before asking or answering a question.'=>'Dodaj pole wyboru, aby użytkownicy mogli zaakceptować twoją taksonomię i warunki, politykę prywatności i wszelkie inne umowy prawne wymagane w twojej jurysdykcji, zanim zadadzą pytanie lub odpowiedzą na nie.','Customize the URL for the login button on Q & A forms. You can override the default URL returned by the WordPress %1$s function with a custom URL specified in this field. If left blank, the standard URL %2$s will be used.'=>'Dostosuj adres URL dla przycisku logowania w formularzach pytań i odpowiedzi. Możesz zastąpić domyślny adres URL zwrócony przez funkcję WordPress %1$s niestandardowym adresem URL określonym w tym polu. Jeśli pole pozostanie puste, zostanie użyty standardowy adres URL %2$s.','Anyone can ask or answer questions'=>'Każdy może zadawać pytania i na nie odpowiadać','Users must be registered and logged in'=>'Użytkownicy muszą być zarejestrowani i zalogowani','Nobody can ask or answer questions'=>'Nikt nie może zadawać pytań ani na nie odpowiadać','Specify permissions for asking and answering questions using Q & A forms.'=>'Określ uprawnienia do zadawania pytań i udzielania odpowiedzi za pomocą formularzy pytań i odpowiedzi.','Q & A Permissions'=>'Uprawnienia do pytań i odpowiedzi','No authorization to ask or answer questions'=>'Brak upoważnienia do zadawania i odpowiadania na pytania','* Question is required'=>'* Pytanie jest wymagane','Your question'=>'Twoje pytanie','Write your answer here'=>'Wpisz tutaj swoją odpowiedź','Your answer'=>'Twoja odpowiedź','Nonce validation error'=>'Błąd walidacji kodu jednorazowego','Global Unique ID'=>'Globalny unikatowy identyfikator','The order contains no items for review. Please reach out to the website administrator for assistance.'=>'Zamówienie nie zawiera żadnych pozycji do recenzji. Skontaktuj się z administratorem witryny, aby uzyskać pomoc.','Reviews received'=>'Otrzymane recenzje','Ratings distribution'=>'Dystrybucja ocen','Average review rating'=>'Średnia ocena recenzji','Ratings'=>'Oceny','Reviews per page'=>'Recenzje na stronę','On-site reviews and other'=>'Recenzje na stronie i inne','In response to reminders'=>'W odpowiedzi na przypomnienia','A license key (either Free or Pro) is required for security purposes to ensure that only you can use CusRev to send review reminders on behalf of your business. No license key is required if you wish to collect reviews locally without third-party verification.'=>'Klucz licencyjny (bezpłatny lub Pro) jest wymagany ze względów bezpieczeństwa, aby zapewnić, że tylko Ty możesz używać CusRev do wysyłania przypomnień o recenzjach w imieniu swojej firmy. Nie jest wymagany żaden klucz licencyjny, jeśli chcesz zbierać recenzje lokalnie bez weryfikacji przez stronę trzecią.','The "Independently Verified" option cannot be activated without a license key (either Free or Pro)'=>'Opcji „Niezależna weryfikacja” nie można włączyć bez klucza licencyjnego (bezpłatnego lub Pro)','Customize the URL for the login button on on-site review forms. You can override the default URL returned by the WordPress %1$s function with a custom URL specified in this field. If left blank, the standard URL %2$s will be used.'=>'Dostosuj adres URL dla przycisku logowania w formularzach recenzji na stronie. Możesz zastąpić domyślny adres URL zwrócony przez funkcję WordPress %1$s niestandardowym adresem URL określonym w tym polu. Jeśli pole pozostanie puste, zostanie użyty standardowy adres URL %2$s.','Login URL'=>'Adres URL logowania','Featured store reviews'=>'Polecane recenzje sklepów','Featured product reviews'=>'Polecane recenzje produktów','%1$s parameter accepts a product ID. Use this parameter to show rating stars of a specific product. If you provide an empty parameter like %2$s and place the shortcode on a WooCommerce product page, it will display a rating of that product.'=>'Parametr %1$s akceptuje identyfikator produktu. Użyj tego parametru, aby wyświetlić gwiazdki oceny konkretnego produktu. Jeśli podasz pusty parametr, taki jak %2$s i umieścisz krótki kod na stronie produktu WooCommerce, wyświetli on ocenę tego produktu.','%1$s parameter accepts %2$s or %3$s and specifies if media files uploaded by customers should be shown in an area above the reviews.'=>'Parametr %1$s akceptuje %2$s lub %3$s i określa, czy pliki multimedialne przesłane przez klientów powinny być wyświetlane w obszarze nad recenzjami.','Image #%1$d from %2$s'=>'Obrazek #%1$d z %2$s','Error: if no valid product ID was provided as a parameter, [cusrev_reviews_rating] shortcode works only on WooCommerce single product pages'=>'Błąd: jeśli nie podano prawidłowego identyfikator produktu jako parametru, krótki kod [cusrev_reviews_rating] działa tylko na stronach pojedynczych produktów w WooCommerce','%1$s parameter is a hex color code of rating stars.'=>'Parametr %1$s to kod szesnastkowy kolorów oznaczający gwiazdki oceny.','Use this shortcode to display a widget with rating stars on any single WooCommerce product page. Here are the default parameters of the shortcode:'=>'Użyj tego krótkiego kodu, aby wyświetlić widżet z gwiazdkami oceny na dowolnej stronie produktu WooCommerce. Oto domyślne parametry krótkiego kodu:','Sort reviews'=>'Sortuj recenzje','Details about the reason why this review reminder was canceled'=>'Szczegóły dotyczące powodu anulowania tego przypomnienia o recenzji','Cancelation reason'=>'Powód anulowania','The free version of the plugin supports up to 2 questions'=>'Bezpłatna wersja wtyczki obsługuje do 2 pytań','CR: a review reminder was not scheduled because reminders are disabled for guests.'=>'CR: przypomnienie o wystawieniu recenzji nie zostało zaplanowane, ponieważ goście mają wyłączoną funkcję przypomnień.','CR: a review reminder was not scheduled because the customer did not have relevant roles.'=>'CR: przypomnienie o recenzji nie zostało zaplanowane, ponieważ klient nie miał odpowiednich ról.','CR: a review reminder was not scheduled because the order did not have products from categories relevant for reminders.'=>'CR: przypomnienie o recenzji nie zostało zaplanowane, ponieważ zamówienie nie zawierało produktów z kategorii objętych przypomnieniami.','Date when this review reminder was canceled'=>'Data anulowania tego przypomnienia o recenzji','Reminder canceled date'=>'Przypomnienie o anulowanej dacie','remindersCanceled <span class="count">(%s)</span>'=>'Anulowano <span class="count">(%s)</span>' . "\0" . 'Anulowano <span class="count">(%s)</span>' . "\0" . 'Anulowano <span class="count">(%s)</span>','There are no review reminders to display'=>'Brak przypomnień o recenzjach do wyświetlenia','Review reminder was canceled by a manual action'=>'Przypomnienie o recenzji zostało anulowane przez działanie ręczne','Canceled'=>'Anulowano','Reviewer received an unconditional discount coupon on future purchases'=>'Recenzent otrzymał bezwarunkowy kupon rabatowy na przyszłe zakupy','Incentivized Badge Label'=>'Etykieta plakietki zachęcającej','Customize label of the incentivized review badge'=>'Dostosuj etykietę plakietki zachęcającej do wystawienia recenzji','Display a badge next to reviews for which customers received discount coupons. Disclosing incentivized reviews helps build trust between customers and your business. It can also be a legal requirement in some jurisdictions.'=>'Wyświetlaj plakietkę obok recenzji, za które klienci otrzymali kupony rabatowe. Ujawnianie zachęcających recenzji pomaga budować zaufanie między klientami a twoją firmą. Może to być również wymóg prawny w niektórych jurysdykcjach.','Incentivized Review Badge'=>'Plakietka zachęcająca recenzji','The free version of the plugin supports up to 3 rating criteria'=>'Bezpłatna wersja wtyczki obsługuje do 3 kryteriów oceniania','Date when a customer opened an aggregated review form from this review reminder'=>'Data otwarcia przez klienta formularza zbiorczej recenzji z tego przypomnienia o recenzji','Review form opened date'=>'Data otwarcia formularza recenzji','Date when a customer viewed this review reminder'=>'Data, kiedy klient wyświetlił to przypomnienie o recenzji','Message opened date'=>'Data otwarcia wiadomości','Date when this review reminder was sent to a customer'=>'Data wysłania tego przypomnienia o recenzji do klienta','Message sent date'=>'Data wysłania wiadomości','Date when this review reminder was created'=>'Data utworzenia tego przypomnienia o recenzji','Reminder created date'=>'Data utworzenia przypomnienia','Tracking details'=>'Szczegóły śledzenia','External ID number for this review reminder'=>'Zewnętrzny numer identyfikacyjny dla tego przypomnienia o recenzji','Tracking ID'=>'Identyfikator śledzenia','Internal ID number for this review reminder'=>'Wewnętrzny numer identyfikacyjny tego przypomnienia o recenzji','ID'=>'Identyfikator','Technical information'=>'Informacje techniczne','Language of this review reminder'=>'Język tego przypomnienia o recenzji','An indicator showing whether this review reminder was sent manually or automatically'=>'Wskaźnik pokazujący, czy przypomnienie o recenzji zostało wysłane ręcznie czy automatycznie','A channel for sending this review reminder'=>'Kanał służący do wysyłania tego przypomnienia o recenzji','An indicator showing whether this review reminder was sent with the independently verified or self-hosted setting'=>'Wskaźnik pokazujący, czy przypomnienie o recenzji zostało wysłane przy użyciu niezależnie zweryfikowanego lub samodzielnie hostowanego ustawienia','Details about the error that occurred while sending this review reminder'=>'Szczegóły dotyczące błędu, który wystąpił podczas wysyłania tego przypomnienia o recenzji','Error description'=>'Opis błędu','Current status of this review reminder'=>'Aktualny status tego przypomnienia o recenzji','Reminder details'=>'Szczegóły przypomnienia','Customer\'s email address for receiving a review invitation'=>'Adres e-mail klienta, na który należy wysłać zaproszenie do wystawienia recenzji','Customer email'=>'E-mail klienta','Customer\'s name for receiving a review invitation'=>'Nazwa klienta, na które ma zostać wysłane zaproszenie do wystawienia recenzji','Customer name'=>'Nazwa klienta','Date when the order status was marked as completed'=>'Data, kiedy status zamówienia został oznaczony jako zrealizowany','Order completed date'=>'Data realizacji zamówienia','Date when the order was paid for'=>'Data zapłaty za zamówienie','Order paid date'=>'Zamówienie opłacone w dniu','Date when the order was created'=>'Data utworzenia zamówienia','Order created date'=>'Data utworzenia zamówienia','Customer order related to the review reminder'=>'Zamówienie klienta związane z przypomnieniem o recenzji','Order details'=>'Szczegóły zamówienia','Reminder #%d'=>'Przypomnienie #%d','Show details'=>'Pokaż szczegóły','Not opened yet'=>'Jeszcze nie otwarte','Not available'=>'Niedostępne','block descriptionDisplay a slider with product and store reviews.'=>'Wyświetl pokaz slajdów z recenzjami produktów i sklepu.','block titleReviews Slider'=>'Pokaz slajdów recenzji','%1$s argument is a hex color code of the external background of the slider.'=>'Argument %1$s jest szesnastkowym kodem koloru zewnętrznego tła pokazu slajdów.','%1$s argument is a hex color code of the external border around the slider.'=>'Argument %1$s jest szesnastkowym kodem koloru zewnętrznej obramowania wokół pokazu slajdów.','%1$s argument accepts a comma-separated list of <a href="%2$s">review tags</a>. Use this argument to show reviews associated with specific tags only.'=>'Argument %1$s akceptuje rozdzieloną przecinkami listę <a href="%2$s">znaczników recenzji</a>. Użyj tego argumentu, aby wyświetlić recenzje powiązane tylko z określonymi znacznikami.','Review invitations have been sent'=>'Zaproszenia do recenzji zostały wysłane','Review invitations to be sent'=>'Zaproszenia do recenzji do wysłania','Error: no authorization to send test emails'=>'Błąd: brak autoryzacji do wysyłania wiadomości testowych','Form opened'=>'Formularz otwarty','Reminder opened'=>'Przypomnienie otwarte','remindersForm Opened <span class="count">(%s)</span>'=>'Formularz otwarty <span class="count">(%s)</span>' . "\0" . 'Formularz otwarty <span class="count">(%s)</span>' . "\0" . 'Formularz otwarty <span class="count">(%s)</span>','Form Opened'=>'Formularz otwarty','Enable this checkbox to discover when customers open emails with review invitations by embedding an invisible pixel into email templates and tracking when it is downloaded. The tracking status will be displayed on the <a href="%s">Reminders</a> page.'=>'Zaznacz to pole wyboru, aby dowiedzieć się, kiedy klienci otwierają wiadomości e-mail z zaproszeniami do recenzji, osadzając niewidoczny piksel w szablonach wiadomości e-mail i śledząc, kiedy jest pobierany. Status śledzenia będzie wyświetlany na stronie <a href="%s">Przypomnienia</a>.','Track Opens'=>'Śledź otwarcia','remindersReminder Opened <span class="count">(%s)</span>'=>'Przypomnienie otwarte <span class="count">(%s)</span>' . "\0" . 'Przypomnienie otwarte <span class="count">(%s)</span>' . "\0" . 'Przypomnienie otwarte <span class="count">(%s)</span>','remindersSent <span class="count">(%s)</span>'=>'Wysłano <span class="count">(%s)</span>' . "\0" . 'Wysłano <span class="count">(%s)</span>' . "\0" . 'Wysłano <span class="count">(%s)</span>','remindersError <span class="count">(%s)</span>'=>'Błąd <span class="count">(%s)</span>' . "\0" . 'Błąd <span class="count">(%s)</span>' . "\0" . 'Błąd <span class="count">(%s)</span>','remindersAll <span class="count">(%s)</span>'=>'Wszystkie <span class="count">(%s)</span>' . "\0" . 'Wszystkie <span class="count">(%s)</span>' . "\0" . 'Wszystkie <span class="count">(%s)</span>','Reminder Opened'=>'Przypomnienie otwarte','* Please tick the checkbox to proceed'=>'* Proszę zaznaczyć pole wyboru, aby kontynuować','Add a checkbox for people to accept your Terms and Conditions, Privacy Policy, and any other legal agreements required in your jurisdiction before submitting a review via an on-site review form.'=>'Dodaj pole wyboru, aby umożliwić użytkownikom zaakceptowanie twojej taksonomii i warunków, polityki prywatności i wszelkich innych umów prawnych wymaganych w twojej jurysdykcji przed przesłaniem recenzji za pośrednictwem formularza recenzji na stronie.','Tailor the text to be shown alongside the Terms and Privacy checkbox. Incorporate links directing users to the Terms and Conditions and Privacy Policy pages on your website.'=>'Dostosuj tekst, który ma być wyświetlany obok pola wyboru taksonomia i prywatność. Umieść odnośniki kierujące użytkowników do stron Taksonomia i Warunki i Polityka prywatności w swojej witrynie internetowej.','Terms and Privacy Checkbox Label'=>'Etykieta pola wyboru regulaminu i polityki prywatności','Terms and Privacy Checkbox'=>'Pole wyboru regulaminu i polityki prywatności','Are you sure you want to delete selected log record(s)?'=>'Czy na pewno chcesz usunąć wybrane rekordy dziennika?','Sent Review Reminders'=>'Wysłane przypomnienia recenzji','Automatic'=>'Automatycznie','Manual'=>'Ręcznie','Sent'=>'Wyślij','Verification'=>'Weryfikacja','The plugin is configured to use CR Cron for sending review reminders (%1$s\'Reminders Scheduler\' setting%2$s).'=>'Wtyczka jest skonfigurowana do używania CR Cron do wysyłania przypomnień o recenzjach (ustawienie %1$s\'Harmonogramu przypomnień\'%2$s).','&hellip;'=>'&hellip;','An error occurred when sending the discount coupon %1$s to the customer by WhatsApp. Error: %2$s.'=>'Wystąpił błąd podczas wysyłania kuponu rabatowego %1$s do klienta przez WhatsApp. Błąd: %2$s.','Anyone can submit reviews'=>'Każdy może przesłać recenzje','Reviewers must be verified owners'=>'Recenzenci muszą być zweryfikowanymi właścicielami','Reviewers must be registered and logged in'=>'Recenzenci muszą być zarejestrowani i zalogowani','Nobody can submit reviews'=>'Nikt nie może zamieszczać recenzji','Specify review permissions for on-site review forms. This setting applies to review forms on single product pages when CusRev visual style is enabled and to review forms added via shortcodes.'=>'Określ uprawnienia do wystawiania recenzji dla formularzy recenzji na stronie. To ustawienie dotyczy formularzy recenzji na stronie (gdy włączony jest styl wizualny) oraz formularzy recenzji dodanych za pomocą krótkich kodów.','Review Permissions'=>'Przejrzyj uprawnienia','Only customers who have purchased this product may leave a review. Please use the same email address as in your order for this product.'=>'Tylko klienci, którzy zakupili ten produkt, mogą zostawić recenzję. Proszę użyć tego samego adresu e-mail, co w zamówieniu tego produktu.','Currently, we are not accepting new reviews'=>'Obecnie nie przyjmujemy nowych recenzji','Message that will be sent to customers via WhatsApp Click to Chat.'=>'Wiadomość, która zostanie wysłana do klientów za pośrednictwem WhatsApp Kliknij, aby porozmawiać.','Send a test WhatsApp message to verify settings for discount coupons.'=>'Wyślij wiadomość testową WhatsApp, aby zweryfikować ustawienia kuponów rabatowych.','WhatsApp Testing'=>'Testowanie WhatsApp','WhatsApp template for messages with discounts can be configured in the %s.'=>'Szablon WhatsApp dla wiadomości ze zniżkami można skonfigurować w %s.','Error: a test message could not be sent.'=>'Błąd: nie można wysłać wiadomości testowej.','An error occurred when sending a test message by WhatsApp.'=>'Wystąpił błąd podczas wysyłania wiadomości testowej przez WhatsApp.','An error occurred when sending a test message by WhatsApp: %s'=>'Wystąpił błąd podczas wysyłania wiadomości testowej przez WhatsApp: %s','An error occurred when sending a test message by WhatsApp: %1$s; %2$s'=>'Wystąpił błąd podczas wysyłania wiadomości testowej przez WhatsApp: %1$s; %2$s','A test message has been successfully sent by WhatsApp to %s.'=>'Wiadomość testowa została pomyślnie wysłana przez WhatsApp do %s.','CR: A review invitation cannot be sent because the order does not contain any products for which review reminders are enabled in the settings.'=>'CR: Nie można wysłać zaproszenia do wystawienia recenzji, ponieważ zamówienie nie zawiera żadnych produktów, dla których w ustawieniach włączono przypomnienia o recenzji.','CR: %1$s cannot be included in a review invitation because it is related to one of the prohibited categories of products. If you would like to send review invitations for this product, please set the \'Verified Reviews\' option to \'Self-hosted\' in the <a href="%2$s">settings</a>.'=>'CR: %1$s nie może zostać uwzględniony w zaproszeniu do recenzji, ponieważ jest powiązany z jedną z zabronionych kategorii produktów. Jeśli chcesz wysłać zaproszenia do recenzji tego produktu, ustaw opcję „Zweryfikowane recenzje” na „Samodzielnie hostowane” w <a href="%2$s">ustawieniach</a>.','A channel for sending discount coupons to customers. For example, by email.'=>'Kanał wysyłania kuponów rabatowych do klientów. Na przykład przez e-mail.','Enable'=>'Włącz','CR: a review reminder was triggered manually via WhatsApp.'=>'CR: przypomnienie o recenzji zostało wysłane ręcznie za pośrednictwem WhatsApp.','CR: a review reminder was triggered manually via email.'=>'CR: przypomnienie o recenzji zostało wysłane ręcznie za pośrednictwem e-mail.','An error occurred when sending the discount coupon %s to the customer by WhatsApp.'=>'Wystąpił błąd podczas wysyłania kuponu rabatowego %s do klienta przez WhatsApp.','Discount coupon %s has been successfully sent to the customer by WhatsApp.'=>'Kupon rabatowy %s został pomyślnie wysłany do klienta przez WhatsApp.','An error occurred when sending the discount coupon %s to the customer by email.'=>'Wystąpił błąd podczas wysyłania kuponu rabatowego %s do klienta poprzez e-mail.','Discount coupon %s has been successfully sent to the customer by email.'=>'Kupon rabatowy %s został pomyślnie wysłany do klienta e-mailem.','Next (arrow right)'=>'Następny (strzałka w prawo)','Previous (arrow left)'=>'Poprzedni (strzałka w lewo)','Zoom in/out'=>'Powiększ/pomniejsz','Toggle fullscreen'=>'Przełącz tryb pełnoekranowy','Share'=>'Udostępnij','Close (Esc)'=>'Zamknij (Esc)','* Please confirm that you are not a robot'=>'* Potwierdź, że nie jesteś robotem','A review reminder has been successfully sent via WhatsApp.'=>'Przypomnienie o recenzji zostało pomyślnie wysłane przez WhatsApp.','Error: a review reminder could not be sent because reviews(s) have already been collected via a local review form for this order.'=>'Błąd: nie można wysłać przypomnienia o wystawieniu recenzji, ponieważ recenzje dla tego zamówienia zostały już zebrane za pomocą lokalnego formularza recenzji.','%1$s has posted new review(s) about your store and/or products. Here is a copy of their review(s):%2$s'=>'%1$s opublikował(a) nową(e) recenzję(e) o twoim sklepie i/lub produktach. Oto kopia ich recenzji:%2$s','Your user account does not have permissions for sending review reminders.'=>'Twoje konto użytkownika nie ma uprawnień do wysyłania przypomnień o recenzji.','Value'=>'Wartość','DNS records are used for DKIM authentication. Publish CNAME records from the table below to your domain’s DNS provider to enable DKIM signature for emails sent by CusRev mailer.'=>'Rekordy DNS są używane do uwierzytelniania DKIM. Opublikuj rekordy CNAME z poniższej tabeli u dostawcy DNS swojej domeny, aby włączyć podpis DKIM dla wiadomości e-mail wysyłanych przez program pocztowy CusRev.','DNS Records'=>'Rekordy DNS','DKIM signature'=>'Podpis DKIM','DKIM stands for DomainKeys Identified Mail. DKIM-signed messages help receiving mail servers validate that a message was not forged or altered in transit. Enabling DKIM reduces the risk that your emails could go to SPAM.'=>'DKIM to skrót od Domain Keys Identified Mail. Wiadomości podpisane DKIM pomagają serwerom pocztowym odbierającym weryfikować, czy wiadomość nie została sfałszowana lub zmieniona w trakcie przesyłania. Włączenie DKIM zmniejsza ryzyko, że twoje wiadomości e-mail trafią do SPAM-u.','Email verification'=>'Weryfikacja e-mail','Before you can send emails via CusRev (AWS SES) mailer, it is necessary to verify that you own the email address. If you have not verified an email address yet, click on the Verify button to start the verification process.'=>'Zanim będziesz mógł wysyłać e-maile za pośrednictwem poczty CusRev (AWS SES), konieczne jest zweryfikowanie, że jesteś właścicielem adresu e-mail. Jeśli jeszcze nie zweryfikowałeś adresu e-mail, kliknij przycisk Weryfikuj, aby rozpocząć proces weryfikacji.','Pending'=>'Oczekująca','DNS record copied'=>'Skopiowano rekord DNS','A security token expired, please refresh the page and try again.'=>'Token bezpieczeństwa wygasł. Odśwież stronę i spróbuj ponownie.','store manager'=>'kierownik sklepu','Log In'=>'Zaloguj się','You must be logged in to post a review'=>'Musisz być zalogowany, aby opublikować recenzję','Only customers who have purchased this product may leave a review'=>'Tylko klienci, którzy kupili ten produkt, mogą pozostawić recenzję','There are no reviews yet'=>'Nie ma jeszcze żadnych recenzji','The file cannot be uploaded because its size exceeds the limit of %d MB'=>'Nie można przesłać pliku, ponieważ jego rozmiar przekracza limit %d MB','\'Form Body\' field cannot be longer than 1024 characters'=>'Pole „Treść formularza” nie może zawierać więcej niż 1024 znaków','%1$s parameter accepts %2$s, %3$s or a product ID. Use it to display a form to write a new review. If the shortcode is placed on a page of a product and the parameter is set to %2$s, the review form will correspond to that product. If the shortocode is placed on a non-product page and the parameter is set to %2$s, the review form will collect shop reviews. If the parameter is set to a product ID, the review form will correspond to a product with that ID.'=>'Parametr %1$s akceptuje %2$s, %3$s lub identyfikator produktu. Użyj go, aby wyświetlić formularz do napisania nowej recenzji. Jeśli krótki kod zostanie umieszczony na stronie produktu, a parametr zostanie ustawiony na %2$s, formularz recenzji będzie odpowiadał temu produktowi. Jeśli krótki kod zostanie umieszczony na stronie innej niż produkt, a parametr zostanie ustawiony na %2$s, formularz recenzji będzie zbierał recenzje sklepu. Jeśli parametr zostanie ustawiony na identyfikator produktu, formularz recenzji będzie odpowiadał produktowi o tym identyfikatorze.','Error: no product with ID %d found'=>'Błąd: nie znaleziono produktu o identyfikatorze %d','Return to messages'=>'Powrót do wiadomości','Send a test message to this phone number by WhatsApp. You must save changes before sending a test message.'=>'Wyślij wiadomość testową na ten numer telefonu przez WhatsApp. Musisz zapisać zmiany przed wysłaniem wiadomości testowej.','A link to an aggregated review form.'=>'Odnośnik do formularza zbiorczej recenzji.','Review Reminder (Click to Chat)'=>'Przypomnienie o recenzji (kliknij, aby porozmawiać)','Message'=>'Wiadomość','WhatsApp Template'=>'Szablon WhatsApp','Adjust templates of WhatsApp messages that will be sent to customers.'=>'Dostosuj szablony wiadomości WhatsApp, które będą wysyłane do klientów.','WhatsApp Templates'=>'Szablony WhatsApp','Messages'=>'Wiadomości','Error: a test review form could not be created.'=>'Błąd: nie udało się utworzyć formularza recenzji testowej.','Error: phone number is not valid. Use a full phone number in international format. Omit any zeroes, brackets, or dashes.'=>'Błąd: numer telefonu jest nieprawidłowy. Użyj pełnego numeru telefonu w formacie międzynarodowym. Pomiń wszelkie zera, nawiasy lub myślniki.','A test review form is ready. Click on the button to send a WhatsApp message.'=>'Formularz recenzji testowej jest gotowy. Kliknij przycisk, aby wysłać wiadomość WhatsApp.','Starting a test...'=>'Rozpoczęcie testu...','Review reminders'=>'Przypomnienia o recenzji','A channel for sending review invitations to customers. For example, by email.'=>'Kanał wysyłania zaproszeń do recenzji klientom. Na przykład przez e-mail.','Channel'=>'Kanał','If automatic review reminders are enabled, review invitations will be sent N days after order status is changed to the value specified in the field below. N is a sending delay (in days) that needs to be defined here.'=>'Jeśli włączone są automatyczne przypomnienia o recenzjach, zaproszenia do recenzji zostaną wysłane N dni po zmianie statusu zamówienia na wartość określoną w polu poniżej. N to opóźnienie wysłania (w dniach), które należy tutaj zdefiniować.','Delay (Days)'=>'Opóźnienie (dni)','Sending delay settings for automatic review reminders.'=>'Ustawienia opóźnienia wysyłania automatycznych przypomnień o recenzji.','Sending Delay'=>'Opóźnienie wysyłania','A review invitation cannot be sent by WhatsApp because no phone number is found in the order.'=>'Nie można wysłać zaproszenia do wystawienia recenzji przez WhatsApp, ponieważ w zamówieniu nie znaleziono numeru telefonu.','Would you like to be invited to review your order? Check here to receive a message from CusRev (an independent reviews service) with a review form.'=>'Czy chcesz otrzymać zaproszenie do przejrzenia swojego zamówienia? Zaznacz tutaj, aby otrzymać wiadomość od CusRev (niezależnej usługi recenzji) z formularzem recenzji.','Comment: %s'=>'Komentarz: %s','Rating: %d star(s)'=>'Ocena: %d gwiazdek','Manage Reviews'=>'Zarządzaj recenzjami','Notification about new reviews'=>'Powiadomienie o nowych recenzjach','New Review(s) from {customer_name}'=>'Nowe recenzje od {customer_name}','CR: a review reminder was sent via WhatsApp manually.'=>'CR: przypomnienie o recenzji zostało wysłane ręcznie przez WhatsApp.','Incorrect: %s'=>'Nieprawidłowo: %s','Correct: %s'=>'Prawidłowo: %s','Examples'=>'Przykłady','Check that the customer\'s phone number %s is formatted correctly.'=>'Sprawdź, czy numer telefonu klienta %s jest poprawnie sformatowany.','Have you sent the review invitation?'=>'Czy wysłałeś zaproszenie do recenzji?','Send'=>'Wyślij','Has the customer provided a consent to receive a review invitation?'=>'Czy klient wyraził zgodę na otrzymanie zaproszenia do wystawienia recenzji?','WhatsApp'=>'WhatsApp','Error: invalid order ID'=>'Błąd: nieprawidłowy identyfikator zamówienia','Error: an option to limit review reminders is enabled in the settings'=>'Błąd: w ustawieniach włączono opcję ograniczenia przypomnień o recenzjach','Error: order %s does not exist'=>'Błąd: zamówienie %s nie istnieje','Error: invalid order ID.'=>'Błąd: nieprawidłowy identyfikator zamówienia.','Set up additional rating criteria for on-site review forms. Use the additional criteria to let your customers rate various features of products. For example, if you are selling footwear, you might want to ask customers to rate features like comfort, value for money, and style.'=>'Ustaw dodatkowe kryteria oceny dla formularzy recenzji na stronie. Użyj dodatkowych kryteriów, aby umożliwić klientom ocenę różnych cech produktów. Na przykład, jeśli sprzedajesz obuwie, możesz poprosić klientów o ocenę takich cech, jak wygoda, stosunek jakości do ceny i styl.','Rating Criteria'=>'Kryteria oceny','Would you like to delete this rating?'=>'Czy chcesz usunąć tę ocenę?','E.g., Comfort'=>'Np. Komfort','* Rating cannot be blank'=>'* Ocena nie może być pusta','E.g., How comfortable are the shoes?'=>'Np. Jak wygodne są buty?','Add a Rating'=>'Dodaj ocenę','Add Rating'=>'Dodaj ocenę','No rating criteria added'=>'Nie dodano kryteriów oceny','This field can be used to require customers to submit a rating.'=>'To pole można wykorzystać, aby poprosić klientów o wystawienie oceny.','A label to be displayed on a review next to a rating provided by a customer. For example, \'Comfort\'.'=>'Etykieta wyświetlana w recenzji obok oceny wystawionej przez klienta. Na przykład „Komfort”.','A question to be displayed for the rating on an on-site review form. For example, \'How comfortable are these shoes?\'.'=>'Pytanie wyświetlane w celu oceny w formularzu recenzji na stronie. Na przykład: „Jak wygodne są te buty?”.','Edit Rating'=>'Edytuj ocenę','* Answer is required'=>'* Odpowiedź jest wymagana','Overall rating'=>'Ocena ogólna','A review reminder cannot be sent because the customer did not provide their consent'=>'Nie można wysłać przypomnienia o wystawieniu recenzji, ponieważ klient nie wyraził na to zgody','CR: a review reminder was not scheduled because the customer did not provide their consent.'=>'CR: przypomnienie o recenzji nie zostało zaplanowane, ponieważ klient nie wyraził na to zgody.','Question'=>'Pytanie','The review form template for review reminders can be configured on the <a href="%s">Forms</a> tab.'=>'Szablon formularza recenzji dla przypomnień o recenzji można skonfigurować na karcie <a href="%s">Formularze</a>.','Would you like to delete this question?'=>'Czy chcesz usunąć to pytanie?','Confirm'=>'Potwierdź','E.g., Skin type'=>'Np. Rodzaj skóry','* Question cannot be blank'=>'* Pytanie nie może być puste','E.g., What is your skin type?'=>'Np. Jaki masz rodzaj skóry?','Add a Question'=>'Dodaj pytanie','Required'=>'Wymagana','Type'=>'Rodzaj','Label'=>'Etykieta','Add Question'=>'Dodaj pytanie','Aggregated Review Form'=>'Zbiorczy formularz recenzji','Enable attachment of images and videos to reviews left on WooCommerce product pages.'=>'Włącz dołączanie obrazków i filmów do recenzji zamieszczonych na stronach produktów WooCommerce.','Set up additional questions for on-site review forms. Use the additional questions to get more information from your customers beyond star ratings and reviews. For example, if you are selling skincare products, you might want to ask customers about their skin type.'=>'Skonfiguruj dodatkowe pytania do formularzy recenzji na stronie. Użyj dodatkowych pytań, aby uzyskać od klientów więcej informacji poza ocenami gwiazdkowymi i recenzjami. Na przykład, jeśli sprzedajesz produkty do pielęgnacji skóry, możesz chcieć zapytać klientów o ich rodzaj skóry.','On-site Product Review Form'=>'Formularz recenzji produktu na stronie','An aggregated review form is a review form that supports collection of reviews for multiple products at the same time. The plugin will automatically create an aggregated review form when sending a review reminder. You can read more about aggregated review forms on <a href="%s">this page</a> of our Helpdesk.'=>'Zbiorczy formularz recenzji to formularz recenzji, który obsługuje zbieranie recenzji dla wielu produktów w tym samym czasie. Wtyczka automatycznie utworzy zagregowany formularz recenzji podczas wysyłania przypomnienia o recenzji. Możesz przeczytać więcej o zagregowanych formularzach recenzji na <a href="%s">tej stronie</a> naszego Biura pomocy.','On-site product review forms are displayed on your website. If reviews are enabled, WooCommerce displays them on product pages. However, on-site review forms can also be displayed using <a href="%s">shortcodes</a> or blocks.'=>'Formularze recenzji produktów na stronie są wyświetlane w twojej witrynie. Jeśli włączony jest styl wizualny, będą wyświetlane na stronach produktów. Formularze mogą też być wyświetlane za pomocą <a href="%s">krótkich kodów</a> lub bloków.','Review Forms'=>'Formularze recenzji','This field can be used to require customers to answer a question.'=>'To pole można wykorzystać, aby poprosić klientów o odpowiedź na pytanie.','A type of question defines what kind of answers a customer can submit.'=>'Rodzaj pytania definiuje, jakiego rodzaju odpowiedzi może udzielić klient.','A label to be displayed on a review next to a customer\'s answer to a question. For example, \'Age\'.'=>'Etykieta wyświetlana w recenzji obok odpowiedzi klienta na pytanie. Na przykład „Wiek”.','A question to be displayed on an on-site review form. For example, \'How old are you?\'.'=>'Pytanie, które ma być wyświetlane w formularzu recenzji na stronie. Na przykład: „Ile masz lat?”.','No questions added'=>'Nie dodano żadnych pytań','Move down'=>'Przesuń w dół','Move up'=>'Przesuń w górę','Edit Customer Attribute'=>'Edytuj atrybut klienta','Number'=>'Liczba','Text'=>'Tekst','A similar question has already been asked. Please rephrase your question.'=>'Podobne pytanie już zostało zadane. Proszę przeformułować pytanie.','A similar answer has already been provided. Please rephrase your answer.'=>'Podobna odpowiedź została już udzielona. Proszę przeformułować swoją odpowiedź.','Line %1$d >> A media file could not be imported due to its type.'=>'Wiersz %1$d >> Nie można zaimportować pliku multimedialnego ze względu na jego rodzaj.','Line %1$d >> An error occurred while downloading a media file.'=>'Wiersz %1$d >> Wystąpił błąd podczas pobierania pliku multimedialnego.','Line %1$d >> An error occurred while downloading a media file. Error code: %2$s. File name: %3$s'=>'Wiersz %1$d >> Wystąpił błąd podczas pobierania pliku multimedialnego. Kod błędu: %2$s. Nazwa pliku: %3$s','Error: no shop page configured in WooCommerce settings (WooCommerce > Settings > Products > Shop page)'=>'Błąd: brak skonfigurowanej strony sklepu w ustawieniach WooCommerce (WooCommerce > Ustawienia > Produkty > Strona sklepu)','Upload images or videos'=>'Prześlij obrazki lub filmy','Product ratings will not be displayed because WooCommerce product reviews are disabled.'=>'Oceny produktów nie będą wyświetlane, ponieważ funkcja recenzji produktów w WooCommerce jest wyłączona.','The plugin is based on the standard WooCommerce product reviews. Please make sure they are enabled in WooCommerce settings (go to WooCommerce > Settings, then click on the \'Products\' tab).'=>'Wtyczka jest oparta na standardowych recenzjach produktów WooCommerce. Upewnij się, że są włączone w ustawieniach WooCommerce (przejdź do WooCommerce > Ustawienia, a następnie kliknij kartę „Produkty”).','WooCommerce Reviews:'=>'Recenzje WooCommerce:','block descriptionDisplay a Trust Badge with a summary of product and store reviews.'=>'Wyświetl Plakietkę Zaufania z podsumowaniem recenzji produktów i sklepu.','block descriptionDisplay a grid with product and store reviews using a masonry layout.'=>'Wyświetl siatkę z recenzjami produktów i sklepów, korzystając z układu cegiełkowego.','%1$s parameter accepts %2$s or a comma-separated list of <a href="%3$s">product IDs</a>. Use this parameter to show reviews of the current product only or reviews corresponding to product IDs from the comma-separated list. If you provide an empty list of product IDs like %4$s, the shortcode will display reviews of all products.'=>'Parametr %1$s akceptuje %2$s lub rozdzieloną przecinkami listę <a href="%3$s">identyfikatorów produktów</a>. Użyj tego parametru, aby wyświetlić recenzje tylko bieżącego produktu lub recenzje odpowiadające identyfikatorom produktów z listy rozdzielonej przecinkami. Jeśli podasz pustą listę identyfikatorów produktów, taką jak %4$s, krótki kod wyświetli recenzje wszystkich produktów.','block titleTrust Badge'=>'Plakietka zaufania','Once in %d day'=>'Raz na %d dzień' . "\0" . 'Raz na %d dni' . "\0" . 'Raz na %d dni','XML feeds with products and product reviews will be refreshed every N days. N is a refresh frequency that needs to be set in this field.'=>'Kanały XML z produktami i recenzjami produktów będą odświeżane co N dni. N to częstotliwość odświeżania, która musi zostać ustawiona w tym polu.','Refresh Frequency'=>'Częstotliwość odświeżania','When active, an XML file with product reviews for Google Shopping will be created immediately after saving settings and then updated according to the Refresh Frequency setting.'=>'Po aktywacji plik XML z recenzjami produktów dla usługi Zakupy Google zostanie utworzony natychmiast po zapisaniu ustawień, a następnie zaktualizowany zgodnie z ustawieniem Częstotliwości odświeżania.','Product Review Feed'=>'Kanał recenzji produktu','When active, an XML file with products for Google Shopping will be created immediately after saving settings and then updated according to the Refresh Frequency setting.'=>'Po aktywacji plik XML z produktami dla usługi Zakupy Google zostanie utworzony natychmiast po zapisaniu ustawień, a następnie zaktualizowany zgodnie z ustawieniem Częstotliwości odświeżania.','Product Feed'=>'Kanał produktu','* Email is required'=>'* E-mail jest wymagany','* Name is required'=>'* Imię jest wymagane','* Review is required'=>'* Recenzja jest wymagana','* Rating is required'=>'* Ocena jest wymagana','WPML/Polylang Automatic'=>'WPML/Polylang Automatyczny','Maximum Size of Media File'=>'Maksymalny rozmiar pliku multimedialnego','Quantity of Media Files'=>'Ilość plików multimedialnych','Attach Images/Videos'=>'Dołączanie obrazków/filmów','Upload up to %d images or videos'=>'Prześlij do %d obrazków lub filmów','Error: accepted file types are PNG, JPG, JPEG, GIF, MP4, MPEG, OGG, WEBM, MOV, AVI'=>'Błąd: akceptowane typy plików to PNG, JPG, JPEG, GIF, MP4, MPEG, OGG, WEBM, MOV, AVI','Continue'=>'Kontynuuj','Your review has been successfully added'=>'Twoja recenzja została pomyślnie dodana','Your review could not be added'=>'Twoja recenzja nie mogła zostać dodana','Data validation error'=>'Błąd weryfikacji danych','Reviews with the lowest rating first'=>'Najpierw recenzje z najniższą oceną','Reviews with the highest rating first'=>'Najpierw recenzje z najwyższą oceną','Lowest Rating'=>'Najniższa Ocena','Highest Rating'=>'Najwyższa ocena','Display a special %s icon next to reviews received in the Live mode together with a nofollow link to the verified copy of the review published on CusRev.com'=>'Wyświetlanie specjalnej ikony %s obok recenzji otrzymanych w trybie Live wraz z linkiem nofollow do zweryfikowanej kopii recenzji opublikowanej na CusRev.com','Links to Reviews'=>'Odnośniki do recenzji','Unverify'=>'Cofnij weryfikację','Would you like to remove verification from this review?'=>'Czy chcesz usunąć weryfikację z tej recenzji?','Age Restriction setting update error #99.'=>'Błąd aktualizacji ustawień ograniczenia wiekowego #99.','Age Restriction setting update error: the page is blocked, please contact CusRev support for assistance.'=>'Błąd aktualizacji ustawień ograniczenia wiekowego: strona jest zablokowana, skontaktuj się z pomocą techniczną CusRev w celu uzyskania pomocy.','Age Restriction setting has been successfully updated.'=>'Ustawienie ograniczenia wiekowego zostało pomyślnie zaktualizowane.','Age Restriction setting update error #98. Please try again.'=>'Błąd aktualizacji ustawień ograniczenia wiekowego #98. Proszę spróbować ponownie.','Live mode activation error #99.'=>'Błąd aktywacji trybu Live #99.','Live mode has been successfully enabled.'=>'Tryb Live został pomyślnie włączony.','Live mode activation error #98. '=>'Błąd aktywacji trybu Live #98. ','Turn on the Live mode after you complete testing and are ready to collect reviews from real customers'=>'Włącz tryb Live, gdy zakończysz testy i będziesz gotowy do zbierania recenzji od prawdziwych klientów.','It is not possible to remove, moderate or hide reviews received in the Live mode'=>'Nie ma możliwości usuwania, moderowania lub ukrywania recenzji otrzymanych w trybie Live','Live mode'=>'Tryb Live','Mode'=>'Tryb','Set a page where customers will be taken to after clicking on a Trust Badge.'=>'Ustaw stronę, na którą zostaną przeniesieni klienci po kliknięciu na odznakę zaufania.','Reviews Page'=>'Strona z recenzjami','Make Trust Badges clickable by adding a link leading to a special page of your website. Use that page to showcase reviews with one of the <a href="%s">shortcodes or Gutenberg blocks</a>.'=>'Spraw, by Odznaki zaufania były klikalne, dodając odnośnik prowadzący do specjalnej strony w twojej witrynie. Użyj tej strony, aby pokazać recenzje za pomocą jednego z <a href="%s">shortcode\'ów lub bloków Gutenberg</a>.','Trust Badge Link'=>'Link do odznaki zaufania','%1$s parameter accepts %2$s or %3$s. Use it to display reviews written by anyone or only the current WordPress user.'=>'Parametr %1$s akceptuje %2$s lub %3$s. Użyj go, aby wyświetlić recenzje napisane przez każdego lub tylko bieżącego użytkownika WordPress.','Use the material attribute to describe the main fabric or material that your product is made of.'=>'Użyj atrybutu materiał, aby opisać główną tkaninę lub materiał, z którego wykonany jest twój produkt.','Material attribute for Google Shopping'=>'Atrybut Materiał dla Google Shopping','Product Material'=>'Materiał produktu','Add a material attribute to WooCommerce products (on \'General\' tab). Use the material attribute to describe the main fabric or material that your product is made of.'=>'Dodaj atrybut Materiał do produktów WooCommerce (na karcie "Ogólne"). Użyj atrybutu materiału, aby opisać główną tkaninę lub materiał, z którego wykonany jest twój produkt.','Material'=>'Materiał','0 of 0 reviews'=>'0 z 0 recenzji','0 of 0 reviews (%s). %s'=>'0 z 0 recenzji (%s). %s','%d-%d of %d review'=>'%d-%d z %d recenzji' . "\0" . '%d-%d z %d recenzji' . "\0" . '%d-%d z %d recenzji','%d-%d of %d review (%s). %s'=>'%d-%d z %d recenzji (%s). %s' . "\0" . '%d-%d z %d recenzji (%s). %s' . "\0" . '%d-%d z %d recenzji (%s). %s','%d star'=>'%d gwiazdka' . "\0" . '%d gwiazdki' . "\0" . '%d gwiazdek','Hidden'=>'Ukryte','If this product is a bundle, use the is_bundle attribute to flag it as bundle in the XML Product Feed for Google Shopping.'=>'Jeśli ten produkt jest pakietem, użyj atrybutu is_bundle, aby oznaczyć go jako pakiet w pliku produktowym XML dla Google Shopping.','is_bundle'=>'is_bundle','is_bundle attribute for Google Shopping'=>'atrybut is_bundle dla Google Shopping','Default'=>'Domyślne','If this product is a multipack, use the multipack attribute to indicate how many products you’ve grouped together.'=>'Jeśli ten produkt jest multipakiem, użyj atrybutu multipack, aby wskazać, ile produktów zgrupowałeś razem.','Product Bundle'=>'Zestaw produktów','Add a bundle attribute to WooCommerce products (on \'Inventory\' tab). Use the bundle attribute to indicate that you have created a bundle: a main product that you have grouped with other, different products, sold together as one package for a single price.'=>'Dodaj atrybut pakiet do produktów WooCommerce (na karcie „Magazyn”). Użyj atrybutu pakiet, aby wskazać, że utworzyłeś pakiet: główny produkt, który zgrupowałeś z innymi, różnymi produktami, sprzedawanymi razem jako jeden pakiet za jedną cenę.','Bundle'=>'Zestaw','Rated %s out of 5'=>'Oceniono %s na 5','Reviewer'=>'Recenzent','If this product is a multipack, then use the multipack attribute to indicate how many products you’ve grouped together.'=>'Jeśli ten produkt jest multipakiem, użyj atrybutu multipack, aby wskazać, ile produktów zgrupowałeś razem.','Multipack attribute for Google Shopping'=>'Atrybut Multipack dla Google Shopping','Add a Brand field to WooCommerce products (on \'Inventory\' tab). This field refers to a brand of the product.'=>'Dodaj pole Marka do produktów WooCommerce (na karcie „Magazyn”). To pole odnosi się do marki produktu.','Product Multipack'=>'Opakowanie zbiorcze produktu','Add a multipack attribute to WooCommerce products (on \'Inventory\' tab). The multipack attribute refers to multiple identical products that you, the retailer, combine for sale. If you have created a multipack grouping several identical products together, then use the mulitpack attribute to indicate how many products you have grouped together.'=>'Dodaj atrybut opakowanie zbiorcze do produktów WooCommerce (na karcie „Magazyn”). Atrybut opakowanie zbiorcze odnosi się do wielu identycznych produktów, które Ty, sprzedawca detaliczny, łączysz w celu sprzedaży. Jeśli utworzyłeś opakowanie zbiorcze grupujący kilka identycznych produktów, użyj atrybutu opakowanie zbiorcze, aby wskazać, ile produktów zgrupowałeś.','Multipack'=>'Opakowanie zbiorcze','Show more reviews (%d)'=>'Pokaz więcej opinii (%d)','CusRev (enhanced user interface)'=>'CusRev (ulepszony interfejs użytkownika)','WooCommerce (basic user interface)'=>'WooCommerce (podstawowy interfejs użytkownika)','Visual Style'=>'Styl wizualny','Display of Customer Reviews'=>'Wyświetlanie recenzji klientów','If you would like to display reviews in locations other than the standard \'Reviews\' tab on product pages, consider using <a href="%s">shortcodes</a> or Gutenberg blocks provided by the plugin.'=>'Jeśli chcesz wyświetlać recenzje w miejscach innych niż standardowa zakładka "Recenzje" na stronach produktów, rozważ użycie <a href="%s">shortcode\'ów</a> lub bloków Gutenberg dostarczonych przez wtyczkę.','The plugin uses the standard WooCommerce functionality to display reviews on products pages. By default, visual appearance of reviews is controlled by WooCommerce and your active WordPress theme. There is also an option to enable an enhanced visual style for display of reviews on product pages.'=>'Wtyczka wykorzystuje standardową funkcjonalność WooCommerce do wyświetlania recenzji na stronach produktów. Domyślnie wizualny wygląd recenzji jest kontrolowany przez WooCommerce i twój aktywny motyw WordPress. Istnieje również opcja włączenia ulepszonego stylu wizualnego do wyświetlania recenzji na stronach produktów.','Live mode activation error: \'Page URL\' cannot be empty.'=>'Błąd aktywacji trybu na żywo: \'Adres URL strony\' nie może być pusty.','what our clients say'=>'co mówią nasi Klienci','What Our Clients Say'=>'Co mówią nasi Klienci','If you enable <a href="%1$s">verification of reviews</a> and claim a <a href="%2$s">dedicated page</a> at CusRev.com website, trust badges will include a nofollow link to your page there.'=>'Jeśli włączysz <a href="%1$s">weryfikację recenzji</a> i zażądasz <a href="%2$s">dedykowanej strony</a> na stronie CusRev.com, odznaki zaufania będą zawierały link nofollow do twojej strony.','Increase your store\'s conversion rate by placing a "trust badge" on the home, checkout or any other page(s). Let customers feel more confident about shopping on your site by featuring a trust badge that shows a summary of customer reviews. Trust badges can be enabled using shortcodes or blocks in the page editor (blocks require WordPress 5.0 or newer).'=>'Zwiększ współczynnik konwersji swojego sklepu umieszczając "odznakę zaufania" na stronie głównej, stronie zamówienia lub dowolnej innej. Użytkownicy twojej witryny będą czuli się bardziej pewnie, jeśli umieścisz odznakę zaufania, która pokazuje podsumowanie recenzji klientów. Odznaki zaufania można włączyć za pomocą shortcode\'ów lub bloków w edytorze stron (bloki wymagają WordPressa 5.0 lub nowszego).','Page URL'=>'Adres URL strony','Display a public page with verified copies of reviews on CusRev.com'=>'Wyświetl publiczną stronę ze zweryfikowanymi kopiami recenzji na CusRev.com','CusRev.com'=>'CusRev.com','Google permits sharing of reviews between variable products and their variations. Use this setting to specify if identifiers (such as GTIN, MPN or SKU) of variable products themselves, their variations or both will be linked to reviews in the XML feed.'=>'Google zezwala na udostępnianie recenzji między produktami zmiennymi i ich wariantami. Użyj tego ustawienia, aby określić, czy identyfikatory (takie jak GTIN, MPN lub SKU) samych produktów zmiennych, ich wariantów lub obu będą łączone z recenzjami w kanale XML.','Variable Product Identifiers'=>'Zmienne identyfikatory produktów','Download button will be enabled after the license check is complete. If there is no valid Pro license key, the Download button will be disabled.'=>'Przycisk pobierania zostanie włączony po zakończeniu sprawdzania licencji. Jeśli nie ma ważnego klucza licencyjnego Pro, przycisk pobierania będzie nieaktywny.','Pro Add-On'=>'Dodatek Pro','If you have a Pro license key, please download and install a Pro add-on for our plugin to enable additional features. After you download the add-on file in a .zip format, go to the <a href="%s">Plugins</a> page, click on the <strong>Upload Plugin</strong> button, and complete the installation process.'=>'Jeśli masz klucz licencyjny Pro, pobierz i zainstaluj dodatek Pro dla naszej wtyczki, aby włączyć dodatkowe funkcje. Po pobraniu pliku dodatku w formacie.zip przejdź na stronę <a href="%s">Wtyczki</a>, kliknij przycisk <strong>Prześlij wtyczkę</strong> i zakończ proces instalacji.','Pro Add-On Download'=>'Pobierz dodatek Pro','Error: nonce expired, please reload the page and try again'=>'Błąd: kod jednorazowy wygasł, proszę przeładować stronę i spróbować ponownie','View Customer Reviews settings'=>'Zobacz ustawienia Recenzji Klientów','Live mode activation error: the page is blocked, please contact CusRev support for assistance.'=>'Błąd aktywacji trybu Live: strona jest zablokowana, prosimy o kontakt z pomocą techniczną CusRev w celu uzyskania pomocy.','CR: a review reminder was cancelled because the order was cancelled.'=>'CR: przypomnienie o recenzji zostało odwołane, ponieważ zamówienie zostało anulowane.','Enable this option if your store sells age-restricted products (e.g., adult content, alcohol, etc.)'=>'Włącz tę opcję, jeśli twój sklep sprzedaje produkty z ograniczeniami wiekowymi (np. treści dla dorosłych, alkohol itp.).','Age Restriction'=>'Ograniczenie wiekowe','Enable attachment of pictures and videos on local aggregated review forms. This option applies only to aggregated review forms. If you would like to enable attachment of pictures to reviews submitted on WooCommerce product pages, please do it in the settings for on-site review forms.'=>'Włącz dołączanie zdjęć i filmów w lokalnych formularzach recenzji agregowanych. Ta opcja dotyczy tylko formularzy recenzji agregowanych. Jeśli chcesz włączyć dołączanie zdjęć do recenzji przesłanych na stronach produktów WooCommerce, zrób to w ustawieniach formularzy recenzji na stronie.','Add photos or video to your review'=>'Dodaj zdjęcia lub wideo do swojej recenzji','Upload Photos/Video'=>'Prześlij zdjęcia/film','CusRev is unable to collect and verify reviews for certain products'=>'CusRev nie jest w stanie zebrać i zweryfikować recenzji dla niektórych produktów','Review invitations will be sent by CusRev on behalf of your store'=>'Zaproszenia do recenzji będą wysyłane przez CusRev w imieniu twojego sklepu','No restrictions on collection of reviews for prohibited product categories'=>'Brak ograniczeń w zbieraniu recenzji dla kategorii produktów objętych zakazem','Review invitations will be sent by the default mailer from your website'=>'Zaproszenia do recenzji będą wysyłane przez domyślnego mailera z twojej strony internetowej','Collect reviews locally without third-party verification'=>'Zbieraj opinie lokalnie bez weryfikacji przez strony trzecie','The email template of review reminders can be configured on the <a href="%s">Emails</a> tab.'=>'Szablon e-maila przypomnienia o recenzji można skonfigurować na karcie <a href="%s">E-maile</a>.','Verified Reviews'=>'Zweryfikowane recenzje','Enable automatic follow-up emails with an invitation to submit a review. Before enabling this feature, you MUST update your terms and conditions and make sure that customers consent to receive invitations to review their orders. Depending on the location of your customers, it might also be necessary to receive an explicit consent to send review reminders. In this case, it is mandatory to enable the ‘Customer Consent’ option below.'=>'Włącz automatyczne wiadomości e-mail z zaproszeniem do złożenia recenzji. Przed włączeniem tej funkcji MUSISZ zaktualizować swoje warunki i upewnić się, że klienci wyrażają zgodę na otrzymywanie zaproszeń do recenzji swoich zamówień. W zależności od lokalizacji twoich klientów, może być również konieczne otrzymanie wyraźnej zgody na wysyłanie przypomnień o recenzji. W tym przypadku obowiązkowe jest włączenie opcji "Zgoda klienta" poniżej.','Configure the plugin to send automatic or manual follow-up emails (reminders) that collect store and product reviews.'=>'Skonfiguruj wtyczkę, aby wysyłać automatyczne lub ręczne wiadomości follow-up (przypomnienia), które zbierają recenzje sklepu i produktów.','Chinese (Simplified)'=>'Chiński (uproszczony)','Chinese (Traditional)'=>'Chiński (tradycyjny)','Send a test email to verify settings for discount coupons.'=>'Wyślij testową wiadomość e-mail, aby zweryfikować ustawienia dla kuponów rabatowych.','The email template for discounts can be configured on the <a href="%s">Emails</a> tab.'=>'Szablon wiadomości e-mail dla rabatów można skonfigurować w zakładce <a href="%s">E-maile</a>.','Customize the plugin\'s settings for sending discount coupons to customers who left reviews. This feature works only with reviews left in response to review invitations.'=>'Dostosuj ustawienia wtyczki do wysyłania kuponów rabatowych do klientów, którzy zostawili recenzje. Ta funkcja działa tylko z recenzjami pozostawionymi przez klientów w odpowiedzi na zaproszenie do recenzji.','Text color for heading of the email.'=>'Kolor tekstu dla nagłówka wiadomości e-mail.','Background color for heading of the email.'=>'Kolor tła dla nagłówka wiadomości e-mail.','"Reply-To" address'=>'Adres zwrotny (Reply-To)','CusRev (AWS SES)'=>'CusRev (AWS SES)','Review for Discount emails provide discount codes to customers who wrote reviews.'=>'E-maile z "Recenzja w celu uzyskania rabatu" dostarczają kody rabatowe klientom, którzy napisali recenzje.','Review reminders include an invitation to write a review. They are sent to customers who recently purchased something from your store.'=>'Przypomnienia o recenzjach zawierają zaproszenie do napisania recenzji. Są one wysyłane do klientów, którzy niedawno kupili coś w twoim sklepie.','via CR (Local)'=>'przez CR (lokalnie)','Error: a review reminder could not be sent because reviews(s) have already been collected with a CusRev mailer for this order.'=>'Błąd: przypomnienie o recenzji nie mogło zostać wysłane, ponieważ recenzje zostały już zebrane za pomocą mailera CusRev dla tego zamówienia.','Error: a review reminder could not be sent because reviews(s) have already been collected with a WordPress mailer for this order.'=>'Błąd: przypomnienie o recenzji nie mogło zostać wysłane, ponieważ recenzja/recenzje zostały już zebrane za pomocą mailera WordPress dla tego zamówienia.','This form was created by %1$s.'=>'Ten formularz został stworzony przez %1$s.','This form was created by %1$s using %2$s plugin.'=>'Ten formularz został stworzony przez %1$s za pomocą wtyczki %2$s.','By submitting your review, you agree to the <a href="%s" target="_blank" rel="noopener noreferrer">terms and conditions</a>.'=>'Przesyłając swoją recenzję, akceptujesz <a href="%s" target="_blank" rel="noopener noreferrer">regulamin</a>.','Display name'=>'Wyświetlana nazwa','Rate website, customer service and delivery'=>'Oceń stronę internetową, obsługę klienta i dostawę','Your comment'=>'Twój komentarz','Edit your review'=>'Edytuj swoją recenzję','Your response has been recorded.'=>'Twoja odpowiedź została zarejestrowana.','Thank you for submitting a review!'=>'Dziękujemy za przesłanie recenzji!','* Required'=>'* Wymagane','CR: a review reminder was not scheduled because reviews(s) have already been collected with a CusRev mailer for this order.'=>'CR: przypomnienie o recenzji nie zostało zaplanowane, ponieważ recenzja/recenzje zostały już zebrane za pomocą mailera CusRev dla tego zamówienia.','CR: a review reminder was not scheduled because reviews(s) have already been collected with a WordPress mailer for this order.'=>'CR: przypomnienie o recenzji nie zostało zaplanowane, ponieważ recenzja/recenzje zostały już zebrane za pomocą mailera WordPress dla tego zamówienia.','Error: the order %s does not exist anymore.'=>'Błąd: zamówienie %s już nie istnieje.','Manage'=>'Zarządzaj','Disabled'=>'Wyłączono','Enabled'=>'Włączono','From'=>'Od','Subject'=>'Tytuł','Adjust templates of the emails that will be sent to customers. If you enable <b>advanced</b> email templates in your account on the %1$sCusRev website%2$s and use CusRev mailer, they will <b>override</b> the email template below.'=>'Dostosuj szablon wiadomości e-mail, który będzie wysyłany do klientów. Jeśli włączysz <b>zaawansowane</b> szablony wiadomości e-mail na swoim koncie na stronie %1$sstronie CusRev%2$s i użyjesz mailera CusRev, będą one <b>nadpisywać</b> poniższy szablon wiadomości e-mail.','Email Templates'=>'Szablony wiadomości e-mail','Emails'=>'E-maile','Template file deleted from theme.'=>'Plik szablonu został usunięty z motywu.','Template file copied to theme.'=>'Plik szablonu został skopiowany do motywu.','You don&#8217;t have permission to do this.'=>'Nie posiadasz uprawnień do wykonania tej operacji.','Action failed. Please refresh the page and retry.'=>'Akcja nie powiodła się. Proszę odświeżyć stronę i spróbować ponownie.','Are you sure you want to delete this template file?'=>'Czy na pewno chcesz usunąć ten plik szablonu?','Hide template'=>'Ukryj szablon','View template'=>'Zobacz szablon','File was not found.'=>'Plik nie został znaleziony.','To override and edit this email template copy %1$s to your theme folder: %2$s.'=>'Aby zastąpić i edytować ten szablon e-mail, skopiuj %1$s do swojego folderu motywu: %2$s.','Copy file to theme'=>'Skopiuj plik do motywu','This template has been overridden by your theme and can be found in: %s.'=>'Ten szablon został nadpisany przez twój motyw i można go znaleźć w: %s.','Delete template file'=>'Usuń plik szablonu','Email template'=>'Szablon wiadomości e-mail','Return to emails'=>'Powrót do e-maili','A button with a link to the page with Q & A.'=>'Przycisk z linkiem do strony z Q & A.','A copy of the answer posted to the Q & A.'=>'Kopia odpowiedzi zamieszczonej w Q & A.','The name of the product for which a Q & A reply was posted.'=>'Nazwa produktu, dla którego została zamieszczona odpowiedź w Q & A.','The full name of a person who responded to a question.'=>'Pełna nazwa osoby, która odpowiedziała na pytanie.','"BCC" address'=>'Adres "BCC"','Emails will be sent from the email address specified in this field.'=>'Wiadomości e-mail będą wysyłane z adresu e-mail podanego w tym polu.','"From" address'=>'Adres "Od" (Nadawcy)','Name that will be used together with the "From" Address to send emails.'=>'Nazwa, która będzie używana wraz z adresem "Od" do wysyłania e-maili.','"From" name'=>'Nazwa "Od" (Nadawcy)','WordPress Default'=>'Domyślny WordPressa','Software that will be used for sending email messages.'=>'Oprogramowanie, które będzie wykorzystywane do wysyłania wiadomości e-mail.','Mailer'=>'Mailer','Reply notification are sent to customers when somebody posts an answer to their question.'=>'Powiadomienia o odpowiedziach są wysyłane do klientów, gdy ktoś zamieści odpowiedź na ich pytanie.','Q & A Reply Notification'=>'Powiadomienie o odpowiedzi w Q & A','Publish a copy of your reply to <a href="%s" target="_blank" rel="noopener noreferrer">CusRev</a> portal'=>'Opublikuj kopię swojej odpowiedzi na portalu <a href="%s" target="_blank" rel="noopener noreferrer">CusRev</a>.','Enable this option to send notifications when somebody replies to a question. The template of notifications can be configured on the <a href="%s">Emails</a> tab.'=>'Włącz tę opcję, aby wysyłać powiadomienia, gdy ktoś odpowie na pytanie. Szablon powiadomień można skonfigurować w zakładce <a href="%s">E-maile</a>.','Reply Notifications'=>'Powiadomienia o odpowiedziach','block titleReviews Grid'=>'Siatka recenzji','%1$s argument accepts %2$s to sort reviews by date, %3$s to sort reviews by rating, and %4$s to sort reviews by the number of attached images.'=>'%1$s argument akceptuje %2$s, aby posortować recenzje według daty, %3$s, aby posortować recenzje według oceny, oraz %4$s, aby posortować recenzje według liczby dołączonych obrazów.','Add a tag'=>'Dodaj tag','All ratings'=>'Wszystkie oceny','Filter by rating'=>'Filtruj wg oceny','5 stars'=>'5 gwiazdek','4 stars'=>'4 gwiazdki','3 stars'=>'3 gwiazdki','2 stars'=>'2 gwiazdki','All review types'=>'Wszystkie typy recenzji','Filter by review type'=>'Filtruj wg typu recenzji','Store reviews'=>'Recenzje sklepu','Product reviews'=>'Recenzje produktów','Filter'=>'Filtr','Automatic review reminders are disabled'=>'Automatyczne przypomnienia o recenzjach są wyłączone','A review reminder will be scheduled after the status is set to %s'=>'Przypomnienie o recenzji zostanie zaplanowane po ustawieniu statusu na %s','If you would like to send a review reminder manually, please set the order status to %s'=>'Jeśli chcesz ręcznie wysłać przypomnienie o recenzji, ustaw status zamówienia na %s','<strong>%1d</strong> product review (1 star)'=>'<strong>%1d</strong> recenzja produktu (1 gwiazdka)' . "\0" . '<strong>%1d</strong> recenzje produktu (1 gwiazdka)' . "\0" . '<strong>%1d</strong> recenzji produktu (1 gwiazdka)','<strong>%1d</strong> product review (2 stars)'=>'<strong>%1d</strong> recenzja produktu (2 gwiazdki)' . "\0" . '<strong>%1d</strong> recenzje produktu (2 gwiazdki)' . "\0" . '<strong>%1d</strong> recenzji produktu (2 gwiazdki)','<strong>%1d</strong> product review (3 stars)'=>'<strong>%1d</strong> recenzja produktu (3 gwiazdki)' . "\0" . '<strong>%1d</strong> recenzje produktu (3 gwiazdki)' . "\0" . '<strong>%1d</strong> recenzji produktu (3 gwiazdki)','<strong>%1d</strong> product review (4 stars)'=>'<strong>%1d</strong> recenzja produktu (4 gwiazdki)' . "\0" . '<strong>%1d</strong> recenzje produktu (4 gwiazdki)' . "\0" . '<strong>%1d</strong> recenzji produktu (4 gwiazdki)','<strong>%1d</strong> product review (5 stars)'=>'<strong>%1d</strong> recenzja produktu (5 gwiazdek)' . "\0" . '<strong>%1d</strong> recenzje produktu (5 gwiazdek)' . "\0" . '<strong>%1d</strong> recenzji produktu (5 gwiazdek)','Additional settings related to the XML Reviews feed are on the \'Reviews\' tab.'=>'Dodatkowe ustawienia związane z plikiem XML Recenzji Produktów znajdują się w zakładce \'Recenzje\'.','<strong>%1d</strong> product review (all ratings)'=>'<strong>%1d</strong> recenzja produktu (wszystkie oceny)' . "\0" . '<strong>%1d</strong> recenzje produktu (wszystkie oceny)' . "\0" . '<strong>%1d</strong> recenzji produktu (wszystkie oceny)','<strong>%1d</strong> product variation, <strong>%2d</strong> excluded'=>'<strong>%1d</strong> wariant produktu, <strong>%2d</strong> wykluczony' . "\0" . '<strong>%1d</strong> warianty produktu, <strong>%2d</strong> wykluczone' . "\0" . '<strong>%1d</strong> wariantów produktu, <strong>%2d</strong> wykluczonych','Review what products and product categories are excluded on the \'Categories and Products\' tab.'=>'Sprawdź, jakie produkty i kategorie produktów są wykluczone w zakładce "Kategorie i produkty".','<strong>%1d</strong> product, <strong>%2d</strong> excluded'=>'<strong>%1d</strong> produkt, <strong>%2d</strong> wykluczony' . "\0" . '<strong>%1d</strong> produkty, <strong>%2d</strong> wykluczone' . "\0" . '<strong>%1d</strong> produktów, <strong>%2d</strong> wykluczonych','XML Feeds might not be created correctly because WP Cron is disabled'=>'Pliki XML mogą nie być tworzone poprawnie, ponieważ WP Cron jest wyłączony','Review(s)'=>'Recenzja(e)','Reviews that are hidden because products were deleted in WooCommerce.'=>'Recenzje, które są ukryte, ponieważ produkty zostały usunięte w WooCommerce.','Hidden Reviews'=>'Ukryte recenzje','Product rating %s / 5'=>'Ocena produktów %s / 5','Store rating %s / 5'=>'Ocena sklepu %s / 5','CR: a review reminder could not be scheduled via CR Cron. %s Error code: %d.'=>'CR: nie można zaplanować przypomnienia o recenzji za pomocą CR Cron. %s Kod błędu: %d.','product rating'=>'ocena produktów','%s product rating'=>'%s ocen produktu','store rating'=>'ocena sklepu','%s store rating'=>'%s ocen sklepu','rating %s / 5'=>'ocena %s / 5','%s rating'=>'Ocena %s','independently verified'=>'niezależnie zweryfikowany','Independently verified'=>'Niezależnie zweryfikowany','An error occurred while downloading a media file. Error code: %1$s (%2$s). File name: %3$s'=>'Wystąpił błąd podczas pobierania pliku multimedialnego. Kod błędu: %1$s (%2$s). Nazwa pliku: %3$s','CR: a review reminder was cancelled because the order was refunded.'=>'CR: przypomnienie o recenzji zostało anulowane, ponieważ zamówienie zostało zwrócone.','Community support'=>'Wsparcie społeczności','Visit community forums'=>'Odwiedź forum społeczności','Docs'=>'Dokumentacja','View CusRev documentation'=>'Zobacz dokumentację CusRev','Video #%1$d from %2$s'=>'Film #%1$d od %2$s','Choose how customer avatars are displayed on WooCommerce single product pages. You can use either the standard WordPress avatars or avatars created based on initial letters of customer names.'=>'Wybierz, w jaki sposób awatary klientów są wyświetlane na stronach pojedynczych produktów WooCommerce. Możesz użyć standardowych awatarów WordPress lub awatarów utworzonych na podstawie początkowych liter nazw klientów.','Customer Avatars'=>'Awatary klientów','Nonce verification failed.'=>'Weryfikacja nonce nie powiodła się.','All media files have been downloaded.'=>'Wszystkie pliki multimedialne zostały pobrane.','Downloaded the file <b>%1$s</b> attached by <b>%2$s</b> to their review of <b>%3$s</b>. Downloading the next file...'=>'Pobrano plik <b>%1$s</b> przesłany przez <b>%2$s</b> do swojej recenzji <b>%3$s</b>. Pobieranie następnego pliku...','Review ID: %s'=>'Identyfikator recenzji: %s','Review of %s by %s'=>'Recenzja %s od %s','An error occurred while downloading a media file. Error code: %s.'=>'Wystąpił błąd podczas pobierania pliku multimedialnego. Kod błędu: %s.','There is %d media file attached by customers to reviews but not downloaded into WordPress Media Library yet.'=>'Istnieje %d plik multimedialny dołączony przez klientów do recenzji, ale nie został jeszcze pobrany do biblioteki multimediów WordPress.' . "\0" . 'Istnieją %d pliki multimedialne dołączone przez klientów do recenzji, ale nie zostały jeszcze pobrane do biblioteki multimediów WordPress.' . "\0" . 'Istnieje %d plików multimedialnych dołączonych przez klientów do recenzji, ale nie zostały jeszcze pobrane do biblioteki multimediów WordPress.','Downloading of media file(s) was cancelled.'=>'Pobieranie pliku(ów) multimedialnego(ych) zostało anulowane.','Cancelling...'=>'Anulowanie...','Try again'=>'Spróbuj ponownie','Downloading...'=>'Pobieranie...','%1$s argument defines how many reviews will be shown at once. This argument is ignored when %2$s argument is greater than %3$s.'=>'Argument %1$s definiuje ile recenzji zostanie wyświetlonych jednocześnie. Ten argument jest ignorowany, jeżeli argument %2$s jest większy niż %3$s.','Coupons are not enabled in any of the discount tiers for reviews with %d uploaded media file(s)'=>'Kupony nie są aktywne w żadnych z poziomów rabatowych dla recenzji z %d przesłanym/przesłanymi plikiem/plikami multimedialnymi.','Please select an existing coupon for Discount Tier %s.'=>'Proszę wybrać istniejący kupon dla Poziomu rabatowego %s.','Send Test To'=>'Wyślij test do','Simulate sending of different coupons depending on how many photos/videos a customer attached to their review. This field can be changed without saving changes.'=>'Symuluj wysyłanie różnych kuponów w zależności od tego ile zdjęć/filmów klient dołączył do swojej recenzji. To pole może być zmienione bez zapisywania zmian.','Email Testing'=>'E-mail - testowanie','Choose categories'=>'Wybierz kategorie','Search for a product'=>'Wyszukaj produkt','Search for a coupon'=>'Wyszukaj kupon','Role'=>'Rola','Choose roles'=>'Wybierz role','Choose one the discount types for new coupons.'=>'Wybierz jeden z typów zniżek dla nowych kuponów.','New Coupon to Create'=>'Nowy kupon do utworzenia','Specific roles'=>'Konkretne role','All roles'=>'Wszystkie role','Define if discount coupons will be sent to all customers or only to customers with specific roles.'=>'Zdefiniuj, czy kupony rabatowe będą wysyłane do wszystkich klientów, czy tylko do klientów z określonymi rolami.','Enable for roles'=>'Włącz dla ról','New coupon'=>'Nowy kupon','No coupon'=>'Brak kuponu','Choose if a new unique coupon will be created, an existing coupon will be used or no coupon will be offered to customers at each of the discount tiers.'=>'Zdecyduj, czy nowy unikalny kupon zostanie utworzony, istniejący kupon zostanie użyty czy żaden kupon nie będzie oferowany klientom na każdym poziomie rabatowym.','Coupon type'=>'Rodzaj kuponu','4 or more'=>'4 lub więcej','3 or more'=>'3 lub więcej','2 or more'=>'2 lub więcej','1 or more'=>'1 lub więcej','0 or more'=>'0 lub więcej','Set how many media files (photos or videos) a customer should upload with their review to qualify for each of the discount tiers.'=>'Ustal, ile plików multimedialnych (zdjęć lub filmów) klient powinien przesłać wraz z recenzją, aby zakwalifikować się do każdego z poziomów rabatowych.','Photos/videos uploaded'=>'Przesłane zdjęcia/filmy','Discount Tier 3'=>'Poziom rabatowy 3','Discount Tier 2'=>'Poziom rabatowy 2','Use discount tiers to offer customers different coupons depending on the number of photos or videos uploaded with reviews.'=>'Używaj poziomów rabatowych, aby zaoferować klientom różne kupony w zależności od liczby zdjęć lub filmów przesłanych wraz z recenzjami.','Discount Tier 1'=>'Poziom rabatowy 1','The option is not available with the coupon type selected for this discount tier.'=>'Opcja nie jest dostępna przy wybranym rodzaju kuponu dla tego poziomu rabatowego.','Error: the customer has already left a review for a different order in the past.'=>'Błąd: klient pozostawił już recenzję dla innego zamówienia w przeszłości.','While editing the footer text please make sure to keep the unsubscribe link markup: %s'=>'Podczas edytowania tekstu stopki pamiętaj o zachowaniu znacznika odnośnika do anulowania subskrypcji: %s','If sharing is allowed, customers will be able to share their coupons with other people. Otherwise, coupons will be valid only for customers who received them.'=>'Jeśli udostępnianie jest dozwolone, klienci będą mogli dzielić się swoimi kuponami z innymi osobami. W przeciwnym razie, kupony będą dostępne tylko dla klientów, którzy je otrzymali.','Allow sharing'=>'Pozwolenie na udostępnianie','Exclude out-of-stock products from both XML Product and XML Product Review feeds. It is recommended to keep this option disabled because Google determines product availability based on the \'availability\' attribute and does not require removal of out-of-stock products from the XML feeds.'=>'Wyklucz produkty niedostępne w magazynie z obu kanałów XML produktów i recenzji produktów. Zaleca się pozostawienie tej opcji wyłączonej, ponieważ Google określa dostępność produktów na podstawie atrybutu "dostępność" i nie wymaga usuwania produktów niedostępnych z kanałów XML.','Exclude unavailable products'=>'Wyklucz niedostępne produkty','Standard'=>'Standard','Initials'=>'Inicjały','%1$s argument accepts %2$s, %3$s or %4$s and defines how avatars of customers will be displayed on reviews.'=>'Argument %1$s przyjmuje wartości %2$s, %3$s lub %4$s i określa w jaki sposób awatary klientów będą wyświetlane w recenzjach.','Error: "Email Subject" is empty. Please enter a string for the subject line of emails.'=>'Błąd: "Temat wiadomości e-mail" jest pusty. Proszę wprowadzić ciąg znaków dla tematu wiadomości e-mail.','Verified owner'=>'Zweryfikowany właściciel','%1$s parameter accepts a comma-separated list of non-product pages (e.g., regular WordPress pages or posts) or %2$s. If non-product page IDs are provided, the block will display Q & A linked to the corresponding non-product pages. If the parameter is equal to %3$s, the block will display Q & A for all non-product pages in the store.'=>'Parametr %1$s akceptuje rozdzieloną przecinkami listę stron innych niż produkty (np. zwykłe strony WordPress lub wpisy) lub %2$s. Jeśli podano identyfikatory stron innych niż produkty, blok wyświetli pytania i odpowiedzi połączone z odpowiednimi stronami innymi niż produkty. Jeśli parametr jest równy %3$s, blok wyświetli pytania i odpowiedzi dla wszystkich stron innych niż produkty w sklepie.','%1$s parameter accepts a comma-separated list of product IDs or %2$s. If product IDs are provided, the block will display Q & A linked to the corresponding products. If the parameter is equal to %3$s, the block will display Q & A for all products in the store.'=>'Parametr %1$s przyjmuje oddzieloną przecinkami listę identyfikatorów produktów lub %2$s. Jeśli podano identyfikator produktu, blok wyświetli pytania i odpowiedzi związane z odpowiadającymi mu produktami. Jeśli parametr jest równy %3$s, blok wyświetli pytania i odpowiedzi dla wszystkich produktów w sklepie.','Use this shortcode to display a block with Questions and Answers on any page or post. Here are the default parameters of the shortcode:'=>'Użyj tego shortcode, aby wyświetlić blok z Pytaniami i odpowiedziami na dowolnej stronie lub w poście. Oto domyślne parametry tego shortcode:','Error: You tried to upload too many files. The maximum number of files that you can upload is %d.'=>'Błąd: Próbowano przesłać zbyt wiele plików. Maksymalna liczba plików, które możesz przesłać to %d.','Error: please solve the CAPTCHA before uploading files'=>'Błąd: proszę rozwiązać CAPTCHA przed wysłaniem plików','Error: the file(s) is too large'=>'Błąd: plik(i) jest(są) zbyt duży(e)','Go back to: %s'=>'Wróć do: %s','CusRev'=>'CusRev','Unfeature'=>'Usuń wyróżnienie','Feature'=>'Wyróżnij','Featured Review'=>'Wyróżniona recenzja','Uploaded Media'=>'Przesłane media','Questions'=>'Pytania','%1$s argument accepts %2$s or %3$s and specifies if dot indicators will be shown.'=>'Argument %1$s przyjmuje %2$s lub %3$s i określa, czy będą wyświetlane wskaźniki kropek.','Detach?'=>'Odłączyć?','Uploading...'=>'Przesyłanie...','Google Shopping is a service that allows merchants to list their products by uploading a product feed in the <a href="%s">Merchant Center</a>. XML Product Feed is necessary to submit products to Google Shopping. XML Product Review Feed is necessary to show stars for products in Google Shopping search results. The feeds should be maintained in Google Merchant Center account.'=>'Google Shopping (Zakupy Google) to usługa, która umożliwia sprzedawcom wystawianie swoich produktów poprzez załadowanie kanału produktu w <a href="%s">Merchant Center (Centrum Sprzedawcy)</a>. Kanał XML Danych produktowych jest niezbędny do przesłania produktów do Google Shopping. Kanał XML z recenzjami produktów jest niezbędny do wyświetlania gwiazdek dla produktów w wynikach wyszukiwania Google Shopping. Kanały powinny być utrzymywane na koncie Google Merchant Center.','Review Stars in Google Shopping'=>'Gwiazdki recenzji w Google Shopping','Google now expects product identifiers (GTIN, MPN, Brand) to be populated in the structured data markup. Our plugin offers an option to add fields for product identifiers to WooCommerce products.'=>'Google oczekuje teraz, że identyfikatory produktów (GTIN, MPN, Brand) będą wypełnione w znacznikach danych strukturalnych. Nasza wtyczka oferuje opcję dodawania pól dla identyfikatorów produktów do produktów WooCommerce.','It is important to understand that having a valid structured data markup in place makes your website eligible for organic stars in Google but it doesn\'t guarantee that they will be shown. You can test the rich snippets using <a href="%1$s">Google’s Rich Results Test</a>.'=>'Ważne jest, aby zrozumieć, że posiadanie prawidłowego znacznika danych strukturalnych sprawia, że witryna kwalifikuje się do gwiazdek organicznych w Google, ale nie gwarantuje, że będą one wyświetlane. Możesz przetestować rich snippets używając <a href="%1$s">Google\'s Rich Results Test</a>.','The standard WooCommerce functionality already includes structured data markup to display your product reviews effectively within organic search results. This plugin extends the standard functionality and adds some extra markup to help search engines properly crawl your shop.'=>'Standardowa funkcjonalność WooCommerce zawiera już znaczniki danych strukturalnych, aby skutecznie wyświetlać recenzje produktów w organicznych wynikach wyszukiwania. Ta wtyczka rozszerza standardową funkcjonalność i dodaje kilka dodatkowych znaczników, aby pomóc wyszukiwarkom poprawnie indeksować twój sklep.','Review Stars in Google Search Organic Listings'=>'Gwiazdki recenzji w organicznych wynikach wyszukiwania Google','color'=>'kolor','Product attributes required by Google Shopping in some countries'=>'Atrybuty produktu wymagane przez Google Shopping w niektórych krajach','Google Shopping Attribute'=>'Atrybut Google Shopping','Specify mapping of WooCommerce product fields to Google Shopping product attributes that might be required in certain countries for some product categories.'=>'Określ mapowanie pól produktów WooCommerce do atrybutów produktów Google Shopping, które mogą być wymagane w niektórych krajach dla poszczególnych kategorii produktów.','Product Attributes'=>'Atrybuty produktu','Error: no products found for the XML Product Feed. Please check exclusion settings for products and product categories.'=>'Błąd: nie znaleziono produktów dla kanału XML Danych produktowych. Proszę sprawdzić ustawienia wykluczeń dla produktów i kategorii produktów.','Error: XMLWriter PHP extension could not be found. Please reach out to the hosting support to enable it.'=>'Błąd: Nie można znaleźć rozszerzenia PHP XMLWriter. Proszę skontaktować się z obsługą hostingu, aby je włączyć.','Choose language that will be used for various elements of emails and review forms.'=>'Wybierz język, który będzie używany w różnych elementach e-maili i formularzy recenzji.','It was not possible to enable \'Shop Rating\' option because no \'Shop page\' is set in WooCommerce settings (WooCommerce > Settings) on \'Products\' tab. Please configure a \'Shop page\' in WooCommerce settings first.'=>'Nie można było włączyć opcji \'Ocena sklepu\', ponieważ nie ustawiono \'Strony sklepu\' w ustawieniach WooCommerce (WooCommerce > Ustawienia) w zakładce \'Produkty\'. Proszę najpierw skonfigurować \'Stronę sklepu\' w ustawieniach WooCommerce.','%1$s argument defines the minimum number of characters that a review must have to be displayed. If this argument is %2$s, then all reviews (including rating-only reviews) will be displayed.'=>'Argument %1$s określa minimalną liczbę znaków, którą musi posiadać recenzja, aby została wyświetlona. Jeśli ten argument jest %2$s, wtedy wszystkie recenzje (włączając w to recenzje z ocenami) zostaną wyświetlone.','Line %1$d >> Error: email address includes invalid characters.'=>'Linia %1$d >> Błąd: adres e-mail zawiera nieprawidłowe znaki.','%1$s argument defines the number of additional reviews to display after a user presses the \'Show more\' button. If this argument is %2$s, then \'Show more\' button will be hidden and the standard WordPress pagination will be used.'=>'Argument %1$s określa liczbę dodatkowych recenzji do wyświetlenia po naciśnięciu przez użytkownika przycisku \'Pokaż więcej\'. Jeśli ten argument jest %2$s, wtedy przycisk \'Pokaż więcej\' zostanie ukryty i zostanie użyta standardowa paginacja WordPressa.','Based on %s review'=>'Na podstawie %s recenzji' . "\0" . 'Na podstawie %s recenzji' . "\0" . 'Na podstawie %s recenzji','%1$s shortcode is also available as <strong>Reviews Slider</strong> block in the new WordPress Gutenberg page editor (blocks require WordPress 5.0 or newer).'=>'%1$s shortcode jest również dostępny jako blok <strong>Slider recenzji</strong> w nowym edytorze stron WordPress Gutenberg (bloki wymagają WordPress 5.0 lub nowszego).','%1$s argument limits the number of characters that are displayed by default for each review. A \'Show More\' button will be added to display the remaining content for reviews that exceed this limit. If you do not want to limit the number of characters to display, set this argument to %2$s.'=>'Argument %1$s ogranicza liczbę znaków, które są wyświetlane domyślnie dla każdej recenzji. Przycisk \'Pokaż więcej\' zostanie dodany, aby wyświetlić pozostałą treść dla recenzji, które przekraczają ten limit. Jeśli nie chcesz ograniczać liczby znaków do wyświetlenia, ustaw ten argument na %2$s.','%1$s argument accepts %2$s or %3$s and defines if the slider will slide automatically.'=>'Argument %1$s przyjmuje %2$s lub %3$s i określa, czy slider będzie się automatycznie przesuwał.','%1$s argument defines the number of slides to show. It is recommended to keep it between %2$s and %3$s.'=>'Argument %1$s określa ilość slajdów do pokazania. Zaleca się, aby mieściła się ona pomiędzy %2$s a %3$s.','%1$s argument defines the number of product reviews to show. It is recommended to keep it between %2$s and %3$s. If you do not want to show product reviews, set it to %4$s and enable shop reviews (see the parameters below).'=>'Argument %1$s określa ilość recenzji produktów do wyświetlenia. Zaleca się, aby była ona pomiędzy %2$s a %3$s. Jeśli nie chcesz wyświetlać recenzji produktów, ustaw go na %4$s i włącz recenzje sklepu (patrz parametry poniżej).','Use this shortcode to display a slider with reviews on any page or post. Here are the default parameters of the shortcode:'=>'Użyj tego shortcode, aby wyświetlić slider z recenzjami na dowolnej stronie lub postu. Poniżej znajdują się domyślne parametry tego shortcode:','%1$s shortcode is also available as <strong>Reviews Grid</strong> block in the new WordPress Gutenberg page editor (blocks require WordPress 5.0 or newer).'=>'%1$s shortcode jest również dostępny jako blok <strong>Siatka recenzji</strong> w nowym edytorze stron WordPress Gutenberg (bloki wymagają WordPress 5.0 lub nowszego).','%1$s argument defines the number of additional reviews to display after a user presses the \'Show more\' button. If this argument is %2$s, then \'Show more\' button will be hidden.'=>'Argument %1$s określa ilość dodatkowych recenzji do wyświetlenia po naciśnięciu przez użytkownika przycisku \'Pokaż więcej\'. Jeśli ten argument jest %2$s, to przycisk \'Pokaż więcej\' zostanie ukryty.','%1$s argument defines the total number of shop reviews to show. It is recommended to keep it between %2$s and %3$s.'=>'Argument %1$s określa całkowitą liczbę recenzji sklepu do pokazania. Zalecane jest, aby mieściła się ona w przedziale od %2$s do %3$s.','%1$s argument is a hex color code of rating stars on review cards.'=>'Argument %1$s to kod szesnastkowy (HEX) koloru gwiazdek oceny na kartach recenzji.','%1$s argument is a hex color code of the background color of product areas on review cards.'=>'Argument %1$s to kod szesnastkowy (HEX) koloru tła obszarów produktów na kartach recenzji.','%1$s argument is a hex color code of the background of review cards.'=>'Argument %1$s to kod szesnastkowy (HEX) koloru tła kart recenzji.','%1$s argument is a hex color code of the external background of the grid.'=>'Argument %1$s to kod szesnastkowy (HEX) koloru zewnętrznego tła siatki.','%1$s argument is a hex color code of the border around review cards.'=>'Argument %1$s to kod szesnastkowy (HEX) koloru obramowania wokół kart recenzji.','%1$s argument is a hex color code of the external border around the grid of reviews.'=>'Argument %1$s to kod szesnastkowy (HEX) koloru zewnętrznego obramowania wokół siatki recenzji.','%1$s argument accepts a comma-separated list of <a href="%2$s">product categories IDs</a> to show only reviews corresponding to specified categories of products.'=>'Argument %1$s akceptuje listę <a href="%2$s">identyfikatorów kategorii produktów</a> rozdzielonych przecinkami, aby wyświetlić tylko recenzje odpowiadające określonym kategoriom produktów.','%1$s argument defines how reviews are sorted. Possible values are %2$s, %3$s and %4$s.'=>'Argument %1$s określa sposób sortowania recenzji. Możliwe wartości to %2$s, %3$s i %4$s.','%1$s argument accepts %2$s to sort reviews by date and %3$s to sort reviews by rating.'=>'Argument %1$s akceptuje %2$s aby posortować recenzje według daty i %3$s aby posortować recenzje według oceny.','%1$s argument accepts %2$s or %3$s and defines if product names will include links to product pages.'=>'Argument %1$s przyjmuje %2$s lub %3$s i określa, czy nazwy produktów będą zawierały odnośniki do stron produktów.','%1$s argument accepts %2$s or %3$s and defines if pictures and names of products corresponding to the review will be shown below the review.'=>'Argument %1$s przyjmuje wartości %2$s lub %3$s i określa, czy pod recenzją będą wyświetlane zdjęcia i nazwy produktów odpowiadających danej recenzji.','%1$s argument defines the number of product reviews to show. It is recommended to keep it between %2$s and %3$s.'=>'Argument %1$s określa ilość recenzji produktów do wyświetlenia. Zaleca się, aby mieściła się ona w przedziale od %2$s do %3$s.','Use this shortcode to display a grid of reviews on any page or post. Here are the default parameters of the shortcode:'=>'Użyj tego shortcode, aby wyświetlić siatkę recenzji na dowolnej stronie lub w poście. Oto domyślne parametry tego shortcode:','%1$s argument accepts %2$s or %3$s and specifies if replies to reviews will be shown.'=>'Argument %1$s przyjmuje wartości %2$s lub %3$s i określa czy będą pokazywane odpowiedzi na recenzje.','%1$s argument accepts %2$s or %3$s and specifies if reviews corresponding to unpublished products will be shown.'=>'Argument %1$s przyjmuje wartości %2$s lub %3$s i określa czy będą pokazywane recenzje nieopublikowanych produktów.','%1$s argument accepts %2$s or %3$s and specifies if general shop reviews will be shown.'=>'Argument %1$s przyjmuje wartości %2$s lub %3$s i określa, czy będą wyświetlane ogólne recenzje sklepu.','%1$s argument accepts a comma-separated list of <a href="%2$s">product tags</a>. Use this argument to show reviews from products associated with specific tags only.'=>'Argument %1$s akceptuje rozdzieloną przecinkami listę <a href="%2$s">znaczników produktów</a>. Użyj tego argumentu, aby wyświetlić recenzje produktów powiązanych tylko z określonymi znacznikami.','%1$s argument accepts %2$s or %3$s and specifies if product names along with product thumbnails should be shown for each review.'=>'Argument %1$s przyjmuje wartości %2$s lub %3$s i określa czy nazwy produktów wraz z ich miniaturami powinny być wyświetlane dla każdej recenzji.','%1$s argument accepts %2$s or %3$s and specifies if product reviews will be shown.'=>'Argument %1$s akceptuje %2$s lub %3$s i określa, czy będą wyświetlane recenzje produktu.','%1$s argument accepts %2$s or %3$s and specifies if a summary bar should be shown on top of the reviews.'=>'Argument %1$s przyjmuje wartości %2$s lub %3$s i określa czy pasek podsumowujący powinien być wyświetlany na górze recenzji.','%1$s argument accepts %2$s to sort reviews by date and %3$s to sort reviews by upvotes.'=>'Argument %1$s akceptuje %2$s aby posortować recenzje według daty i %3$s aby posortować recenzje według liczby głosów.','%1$s argument defines how reviews are sorted. Possible values are %2$s and %3$s.'=>'Argument %1$s określa sposób sortowania recenzji. Możliwe wartości to %2$s i %3$s.','Parameters:'=>'Parametry:','Use this shortcode to display a list of all reviews on any page or post. Here are the default parameters of the shortcode:'=>'Użyj tego shortcode, aby wyświetlić listę wszystkich recenzji na dowolnej stronie lub postu. Oto domyślne parametry tego shortcode:','The plugin provides several shortcodes and Gutenberg blocks that you can use to display reviews in various places on your website. You can find the list of available shortcodes and their parameters below.'=>'Wtyczka zapewnia kilka shortcodes i bloków Gutenberg, których możesz użyć do wyświetlania recenzji w różnych miejscach na swojej stronie. Listę dostępnych shortcodes i ich parametry znajdziesz poniżej.','Shortcodes and Blocks'=>'Shortcody i bloki','Shortcodes'=>'Shortcody','This is not a duplicate site'=>'To nie jest zduplikowana strona','Please log in to your account on %1$sCusRev website%2$s to view and manage the reminders.'=>'Proszę zalogować się na swoje konto na %1$sstronie CusRev%2$s, aby przeglądać przypomnienia i zarządzać nimi.','The plugin is configured to use CR Cron for scheduling review reminders (%1$s\'Reminders Scheduler\' setting%2$s).'=>'Wtyczka jest skonfigurowana do korzystania z CR Cron do planowania przypomnień o recenzjach (%1$s ustawienia \'Harmonogramu Przypomnień\' %2$s).','Enable this option to display the count of answered questions next to the product rating and under the product name.'=>'Włącz tę opcję, aby obok oceny produktu i pod jego nazwą wyświetlana była liczba pytań, na które udzielono odpowiedzi.','Display Count of Answered Questions'=>'Wyświetl liczbę udzielonych odpowiedzi na pytania','A copy of the reply was published on CusRev portal'=>'Kopia tej odpowiedzi została opublikowana na portalu CusRev','%s answered question'=>'%s osoba odpowiedziała na pytanie' . "\0" . '%s osoby odpowiedziały na pytanie' . "\0" . '%s osób odpowiedziało na pytanie','%s review'=>'%s opinia' . "\0" . '%s opinie' . "\0" . '%s opinii','The plugin checks if this site has moved or is a duplicate site. If the check is positive, the plugin will disable sending automatic review reminder emails to prevent duplicate reminders from a staging or test environment.'=>'Wtyczka sprawdza, czy ta witryna została przeniesiona lub jest zduplikowaną witryną. Jeśli sprawdzenie jest pozytywne, wtyczka wyłączy wysyłanie automatycznych wiadomości e-mail z przypomnieniem o recenzji, aby zapobiec zduplikowanym przypomnieniom ze środowiska etapowego lub testowego.','It looks like this site has moved or is a duplicate site. The plugin has disabled sending automatic review reminder emails on this site to prevent duplicate reminders from a staging or test environment.'=>'Wygląda na to, że ta witryna została przeniesiona lub jest zduplikowaną witryną. Wtyczka wyłączyła wysyłanie automatycznych wiadomości e-mail z przypomnieniem o recenzji w tej witrynie, aby zapobiec zduplikowanym przypomnieniom ze środowiska etapowego lub testowego.','Duplicate Site (disable automatic review reminders):'=>'Duplikat strony (wyłączenie automatycznych przypomnień o recenzji):','The plugin will not be able to receive reviews because REST API is disabled. Additional information can be found in this %ssupport article'=>'Wtyczka nie będzie mogła otrzymywać recenzji, ponieważ interfejs REST API jest wyłączony. Dodatkowe informacje można znaleźć w tym artykule %swsparcie','Sorry, no questions were found'=>'Przepraszamy, nie znaleziono żadnych pytań','Search answers'=>'Szukaj odpowiedzi','(2) Basic features of CusRev service (e.g., review reminders, social media integration, analytics, replies to reviews) are available for free but require a (free) license key. If you would like to request a free license key (no pro features), create an account here => %sFree License Key'=>'(2) Podstawowe funkcje usługi CusRev (np. przypomnienia o recenzjach, integracja z mediami społecznościowymi, analityka, odpowiedzi na recenzje) są dostępne bezpłatnie, ale wymagają (bezpłatnego) klucza licencyjnego. Jeśli chcesz poprosić o bezpłatny klucz licencyjny (bez funkcji pro), utwórz konto tutaj => %sBezpłatny klucz licencyjny','(1) You can unlock <b>all</b> features for managing customer reviews by purchasing a professional license key => %sProfessional License Key'=>'(1) Możesz odblokować <b>wszystkie</b> funkcje do zarządzania recenzjami klientów kupując profesjonalny klucz licencyjny => %sProfesjonalny klucz licencyjny','Customer Reviews (CusRev) service works with two types of license keys: (1) professional and (2) free.'=>'Usługa Customer Reviews (CusRev) działa z dwoma rodzajami kluczy licencyjnych: (1) profesjonalnym i (2) darmowym.','Manually Published'=>'Opublikowane ręcznie','Show Less'=>'Pokaż mniej','Show More'=>'Pokaż więcej','Add an answer'=>'Dodaj odpowiedź','This site is protected by reCAPTCHA and the Google %1$sPrivacy Policy%2$s and %3$sTerms of Service%4$s apply.'=>'Strona jest chroniona przez reCAPTCHA i %1$sPolitykę prywatności Google%2$s i zastosowanie mają %3$sWarunki usług%4$s.','Answer the question'=>'Odpowiedz na pytanie','Line %1$d >> Error: incorrect file format. Only %2$d column(s) found. Please open the input file in a text editor (e.g., in Notepad on Windows) and verify that columns are correctly separated by commas.'=>'Wiersz %1$d >> Błąd: nieprawidłowy format pliku. Znaleziono tylko %2$d kolumn(y). Proszę otworzyć plik wejściowy w edytorze tekstu (np. w Notatniku w systemie Windows) i sprawdzić, czy kolumny są poprawnie oddzielone przecinkami.','If you would like to use reCAPTCHA v3, insert here the Secret Key that you will receive after registration at the reCAPTCHA website.'=>'Jeśli chcesz używać reCAPTCHA v3, wpisz tutaj tajny klucz (Secret Key), który otrzymasz po rejestracji na stronie reCAPTCHA.','reCAPTCHA v3 Secret Key'=>'reCAPTCHA v3 Tajny klucz (Secret Key)','If you would like to use reCAPTCHA v3, insert here the Site Key that you will receive after registration at the reCAPTCHA website.'=>'Jeśli chcesz używać reCAPTCHA v3, wpisz tutaj klucz witryny (Site Key), który otrzymasz po rejestracji na stronie reCAPTCHA.','reCAPTCHA v3 Site Key'=>'Klucz witryny reCAPTCHA v3','Enable reCAPTCHA v3 to eliminate SPAM questions and answers. You must enter a Site Key and a Secret Key in the fields below, if you want to use reCAPTCHA. You will receive these keys after registration at reCAPTCHA website.'=>'Włącz reCAPTCHA v3, aby wyeliminować spamowe pytania i odpowiedzi. Aby korzystać z reCAPTCHA, musisz wprowadzić klucz witryny (Site Key) i tajny klucz (Secret Key) w poniższych polach. Otrzymasz te klucze po rejestracji na stronie reCAPTCHA.','reCAPTCHA v3 for Q & A'=>'reCAPTCHA v3 dla Q & A','The answer was successfully added.'=>'Odpowiedź została dodana.','An error when adding the answer.'=>'Błąd podczas dodawania odpowiedzi.','reCAPTCHA response is missing.'=>'Brak odpowiedzi reCAPTCHA.','reCAPTCHA validation error (%s).'=>'Błąd weryfikacji reCAPTCHA (%s).','reCAPTCHA score is below the threshold.'=>'Wynik reCAPTCHA jest poniżej progu.','Q & A (%d)'=>'Pytania i odpowiedzi (%d)','The last name of the customer who purchased from your store.'=>'Nazwisko klienta, który dokonał zakupu w twoim sklepie.','Question / Answer'=>'Pytanie / Odpowiedź','No questions / answers found.'=>'Nie znaleziono pytań / odpowiedzi.','No questions / answers awaiting moderation.'=>'Brak pytań / odpowiedzi oczekujących na moderację.','Search Q & A'=>'Szukaj w pytaniach i odpowiedziach','This question / answer is already marked as spam.'=>'To pytanie / odpowiedź zostało już oznaczone jako spam.','This question / answer is already in the Trash.'=>'To pytanie / odpowiedź jest już w koszu.','Edit question / answer'=>'Edytuj pytanie / odpowiedź','This question / answer is already approved.'=>'To pytanie / odpowiedź zostało już zatwierdzone.','%s question / answer deleted'=>'%s pytanie / odpowiedź została usunięta' . "\0" . '%s pytania / odpowiedzi zostały usunięte' . "\0" . '%s pytań / odpowiedzi zostało usunięte','%s question / answer restored from the Trash'=>'%s pytanie / odpowiedź została przywrócona z kosza' . "\0" . '%s pytania / odpowiedzi zostały przywrócone z kosza' . "\0" . '%s pytań / odpowiedzi zostało przywróconych z kosza','%s question / answer moved to the Trash.'=>'%s pytanie / odpowiedź została przeniesiona do kosza.' . "\0" . '%s pytania / odpowiedzi zostały przeniesione do kosza.' . "\0" . '%s pytań / odpowiedzi zostało przeniesionych do kosza.','%s question / answer restored from the spam'=>'%s pytanie / odpowiedź została przywrócona ze spamu' . "\0" . '%s pytania / odpowiedzi zostały przywrócone ze spamu' . "\0" . '%s pytań / odpowiedzi zostało przywróconych ze spamu','%s question / answer marked as spam.'=>'%s pytanie / odpowiedź została oznaczona jako spam.' . "\0" . '%s pytania / odpowiedzi zostały oznaczone jako spam.' . "\0" . '%s pytań / odpowiedzi zostało oznaczonych jako spam.','%s question / answer approved'=>'%s pytanie / odpowiedź została zatwierdzona' . "\0" . '%s pytania / odpowiedzi zostały zatwierdzone' . "\0" . '%s pytań / odpowiedzi zostało zatwierdzonych','Sorry, you are not allowed to edit questions / answers for this product.'=>'Przepraszamy, nie możesz edytować pytań / odpowiedzi dotyczących tego produktu.','Invalid question / answer ID.'=>'Nieprawidłowy identyfikator pytania / odpowiedzi.','The question was successfully added.'=>'Pytanie zostało pomyślnie dodane.','An error when adding the question.'=>'Błąd podczas dodawania pytania.','Data validation error.'=>'Błąd weryfikacji danych.','Enable this option to display a tab with questions and answers on product pages.'=>'Włącz tę opcję, aby wyświetlać zakładkę z pytaniami i odpowiedziami na stronach produktów.','Add a tab with questions and answers to product pages on your website. Let your prospective customers ask questions about products and view questions asked by others. Boost sales by answering the questions and making sure that prospective customers have all the information available to make a purchase decision.'=>'Dodaj zakładkę z pytaniami i odpowiedziami do stron produktów w twojej witrynie. Pozwól swoim potencjalnym klientom zadawać pytania dotyczące produktów i przeglądać pytania zadawane przez innych. Zwiększ sprzedaż, odpowiadając na pytania i upewniając się, że potencjalni klienci mają wszystkie informacje potrzebne do podjęcia decyzji o zakupie.','Questions and Answers'=>'Pytania i odpowiedzi','Reply to Question'=>'Odpowiedz na pytanie','Error'=>'Błąd','OK'=>'OK','Your email'=>'Twój adres e-mail','Your name'=>'Twoje imię i nazwisko','Start your question with \'What\', \'How\', \'Why\', etc.'=>'Rozpocznij pytanie od słów: "Co", "Jak", "Dlaczego" itp.','There are no questions yet'=>'Nie ma jeszcze pytań','%s answered on %s'=>'%s odpowiedział(a) w dniu %s','%s asked on %s'=>'%s zapytał(a) w dniu %s','Ask a question'=>'Zadaj pytanie','Q & A'=>'Pytania i odpowiedzi','Reply could not be published to CusRev portal. Error '=>'Odpowiedź nie mogła zostać opublikowana na portalu CusRev. Błąd ','This reply was originally posted on %s. This copy of the reply was modified and might be different from the original published on CusRev portal.'=>'Ta odpowiedź została pierwotnie opublikowana na stronie %s. Kopia odpowiedzi została zmodyfikowana i może różnić się od oryginału opublikowanego na portalu CusRev.','This reply was originally posted on CusRev portal'=>'Odpowiedź została pierwotnie zamieszczona na portalu CusRev','This reply was originally posted on %s. If this copy of the reply is edited, the original reply will NOT be updated. Only the customer can edit the original reply on CusRev portal.'=>'Ta odpowiedź została pierwotnie opublikowana na stronie %s. Jeśli kopia odpowiedzi zostanie edytowana, oryginalna odpowiedź NIE zostanie zaktualizowana. Tylko klient może edytować oryginalną odpowiedź w portalu CusRev.','CusRev portal'=>'Portal CusRev','Export failed: Could not create a folder in %s. Please check folder permissions.'=>'Eksport nie powiódł się: Nie można utworzyć folderu w %s. Proszę sprawdzić uprawnienia do folderu.','A comma-separated list of product IDs that should be excluded from XML Product Feed. Product ID is a number that can found in the URL of the page to edit the product.'=>'Rozdzielona przecinkami lista identyfikatorów produktów, które powinny być wykluczone z pliku danych produktowych XML. identyfikator produktu jest numerem, który można znaleźć w adresie URL strony podczas edycji produktu.','Product IDs'=>'Identyfikatory produktów','Provide a list of WooCommerce products that should be excluded from XML Product Feed. It should be a comma-separated list of product IDs. If all products should be added to XML Product Feed, keep this field empty.'=>'Podaj listę produktów WooCommerce, które powinny być wykluczone z pliku danych produktowych XML. Powinna to być oddzielona przecinkami lista identyfikatorów produktów. Jeśli wszystkie produkty powinny zostać dodane do pliku produktowego XML, zachowaj to pole puste.','Exclude Products'=>'Wyklucz produkty','Categories and Products'=>'Kategorie i produkty','Select a field'=>'Wybierz pole','Select a category'=>'Wybierz kategorię','Error code 2 (%s).'=>'Kod błędu 2 (%s).','Error code 1'=>'Kod błędu 1','Syncing...'=>'Synchronizowanie...','Sending...'=>'Wysyłanie...','Checking...'=>'Sprawdzanie...','Quick Edit'=>'Szybka edycja','No description'=>'Brak opisu','View'=>'Zobacz','View &#8220;%s&#8221; archive'=>'Zobacz archiwum &#8222;%s&#8221;','Delete &#8220;%s&#8221;'=>'Usuń &#8222;%s&#8221;','Select %s'=>'Wybierz %s','Number/count of itemsCount'=>'Liczba','Delete'=>'Usuń','Tags can be selectively converted to categories using the <a href="%s">tag to category converter</a>.'=>'Przy pomocy <a href="%s">konwertera tagów</a> możesz przekształcić wybrane tagi w kategorie.','Categories can be selectively converted to tags using the <a href="%s">category to tag converter</a>.'=>'Wybrane kategorie mogą zostać przekonwertowane na tagi przy pomocy <a href="%s">konwertera kategorii na tagi</a>.','Deleting a category does not delete the posts in that category. Instead, posts that were only assigned to the deleted category are set to the default category %s. The default category cannot be deleted.'=>'Usunięcie kategorii nie spowoduje usunięcia wpisów w tej kategorii. Zamiast tego wpisy, które były przypisane tylko do usuniętej kategorii, będą dodane do domyślnej kategorii: %s. Kategorii domyślnej nie można usunąć.','Assign a parent term to create a hierarchy. The term Jazz, for example, would be the parent of Bebop and Big Band.'=>'Przypisz pojęcie nadrzędne, aby utworzyć hierarchię. Na przykład pojęcie Jazz byłoby nadrzędne dla Bebop i Big Band.','Categories, unlike tags, can have a hierarchy. You might have a Jazz category, and under that have children categories for Bebop and Big Band. Totally optional.'=>'Kategorie, w przeciwieństwie do tagów, mogą zostać uporządkowane w hierarchię. Możesz, na przykład, utworzyć kategorię &#8222;Jazz&#8221;, a jako jej podkategorie oznaczyć kategorie &#8222;Bebop&#8221; i &#8222;Big Band&#8221;. Jest to opcjonalne.','None'=>'Brak','The name is how it appears on your site.'=>'Nazwa, pod jaką element widoczny jest na witrynie.','term nameName'=>'Nazwa','<a href="https://wordpress.org/support/">Support</a>'=>'<a href="https://wordpress.org/support/">Wsparcie</a>','<a href="https://wordpress.org/support/article/posts-tags-screen/">Documentation on Tags</a>'=>'<a href="https://wordpress.org/support/article/posts-tags-screen/">Dokumentacja: tagi [en]</a>','<a href="https://codex.wordpress.org/Links_Link_Categories_Screen">Documentation on Link Categories</a>'=>'<a href="https://codex.wordpress.org/Links_Link_Categories_Screen">Dokumentacja: kategorie linków</a>','<a href="https://wordpress.org/support/article/posts-categories-screen/">Documentation on Categories</a>'=>'<a href="https://wordpress.org/support/article/posts-categories-screen/">Dokumentacja: kategorie</a>','For more information:'=>'Więcej informacji:','Adding Tags'=>'Dodawanie tagów','Adding Categories'=>'Dodawanie kategorii','You can change the display of this screen using the Screen Options tab to set how many items are displayed per screen and to display/hide columns in the table.'=>'Możesz zmienić sposób wyświetlania elementów na tym ekranie przy pomocy karty &#8222;Opcje ekranu&#8221;, gdzie możliwy jest wybór ilości wyświetlanych elementów, a także wyświetlenie/ukrycie kolumn widocznej na tej stronie tabeli.','<strong>Description</strong> &mdash; The description is not prominent by default; however, some themes may display it.'=>'<strong>Opis</strong> - Opis zwykle nie jest eksponowany, jednak niektóre motywy mogą go wyświetlać.','<strong>Parent</strong> &mdash; Categories, unlike tags, can have a hierarchy. You might have a Jazz category, and under that have child categories for Bebop and Big Band. Totally optional. To create a subcategory, just choose another category from the Parent dropdown.'=>'<strong>Rodzic</strong> &mdash; Kategorie, w przeciwieństwie do tagów, mogą posiadać hierarchię. Można utworzyć kategorię Muzyka, a jako jej podkategorie - Jazz i Rock. Wybór należy do ciebie. Aby utworzyć podkategorię, należy w polu Rodzic wybrać kategorię nadrzędną.','<strong>Slug</strong> &mdash; The &#8220;slug&#8221; is the URL-friendly version of the name. It is usually all lowercase and contains only letters, numbers, and hyphens.'=>'<strong>Uproszczona nazwa</strong> - Uproszczona nazwa jest przyjazną systemom komputerowym wersją nazwy elementu, która wykorzystywana jest jako część adresu URL. Zwykle składa się ona wyłącznie z małych liter, cyfr i myślników.','<strong>Name</strong> &mdash; The name is how it appears on your site.'=>'<strong>Nazwa</strong> - Nazwa, pod jaką element widoczny jest na witrynie.','When adding a new tag on this screen, you&#8217;ll fill in the following fields:'=>'Dodawanie nowego tagu na tym ekranie sprowadza się do wypełnienia następujących pól:','When adding a new category on this screen, you&#8217;ll fill in the following fields:'=>'Dodawanie nowej kategorii na tym ekranie sprowadza się do wypełnienia następujących pól:','What&#8217;s the difference between categories and tags? Normally, tags are ad-hoc keywords that identify important information in your post (names, subjects, etc) that may or may not recur in other posts, while categories are pre-determined sections. If you think of your site like a book, the categories are like the Table of Contents and the tags are like the terms in the index.'=>'Jaka jest różnica między kategoriami a tagami? Tagi są zwykle słowami kluczowymi, które informują o najważniejszych sprawach opisywanych przez wpisy (a więc mogą one być nazwami własnymi, tematami itp.) Tagi niekoniecznie muszą występować przy więcej niż jednym wpisie. Kategorie są natomiast z góry określonymi sekcjami witryny. Jeśli wyobrazisz sobie, że twoja witryna jest książką, możesz myśleć o kategoriach jak o rozdziałach, a o tagach jak o skorowidzu.','You can delete Link Categories in the Bulk Action pull-down, but that action does not delete the links within the category. Instead, it moves them to the default Link Category.'=>'Można usuwać Kategorie odnośników używając pola Masowe działania, ale ta akcja nie usuwa odnośników. Zamiast tego, przenosi je do domyślnej kategorii odnośników.','You can assign keywords to your posts using <strong>tags</strong>. Unlike categories, tags have no hierarchy, meaning there&#8217;s no relationship from one tag to another.'=>'Do wpisów można przypisać słowa kluczowe, zwane <strong>tagami</strong>. W przeciwieństwie do kategorii tagi nie mogą zostać uporządkowane w hierarchię, co oznacza, że nie istnieją między nimi żadne zależności.','You can create groups of links by using Link Categories. Link Category names must be unique and Link Categories are separate from the categories you use for posts.'=>'Możesz pogrupować odnośniki przy użyciu kategorii odnośników. Nazwy kategorii odnośników nie mogą się powtarzać. Kategorie odnośników są niezależne od kategorii wpisów.','You can use categories to define sections of your site and group related posts. The default category is &#8220;Uncategorized&#8221; until you change it in your <a href="%s">writing settings</a>.'=>'Można użyć kategorii w celu określenia obszarów witryny lub pogrupowania podobnych wpisów. Domyślną kategorią jest &#8222;Bez kategorii&#8221;, można ją zmienić w <a href="%s">ustawieniach pisania</a>.','Sorry, you are not allowed to edit this item.'=>'Przepraszamy, nie posiadasz uprawnień do edycji tego elementu.','You attempted to edit an item that doesn&#8217;t exist. Perhaps it was deleted?'=>'Próbujesz edytować element, który nie istnieje. Być może został on usunięty?','Sorry, you are not allowed to delete these items.'=>'Przepraszamy, nie posiadasz uprawnień do usunięcia tych elementów.','Sorry, you are not allowed to delete this item.'=>'Przepraszamy, nie posiadasz uprawnień do usunięcia tego elementu.','Sorry, you are not allowed to create terms in this taxonomy.'=>'Brak uprawnień do tworzenia terminów wybranej taksonomii.','Sorry, you are not allowed to manage terms in this taxonomy.'=>'Brak uprawnień do zarządzania terminami z wybranej taksonomii.','You need a higher level of permission.'=>'Potrzebujesz uprawnienia wyższego poziomu.','Sorry, you are not allowed to edit terms in this taxonomy.'=>'Brak uprawnień do edycji terminów wybranej taksonomii.','Invalid taxonomy.'=>'Nieprawidłowa taksonomia.','An error has occurred. Please reload the page and try again.'=>'Wystąpił błąd. Proszę odświeżyć stronę i spróbować ponownie.','Review Tagging'=>'Przejrzyj tagowanie','Tags'=>'Tagi','Tags for Reviews'=>'Tagi recenzji','No tags found'=>'Nie znaleziono żadnego tagu','Choose from the most used tags'=>'Wybierz z najczęściej używanych tagów','Add or remove tags'=>'Dodaj lub usuń tagi','Separate tags with commas'=>'Oddzielaj tagi przecinkami','New Tag Name'=>'Nazwa nowego tagu','Create New Tag'=>'Utwórz nowy tag','Update Tag'=>'Zaktualizuj tag','Edit Tag'=>'Edytuj tag','All Tags'=>'Wszystkie tagi','Popular Tags'=>'Popularne tagi','Search Tags'=>'Szukaj tagów','taxonomy singular nameTag'=>'Tag','taxonomy general nameTags for Reviews'=>'Tagi recenzji','Export Failed'=>'Eksport nie powiódł się','Export Cancelled'=>'Eksport anulowany','Export is in progress (%s/%s completed)'=>'Trwa eksport (%s/%s zakończony)','Export Reviews to CSV File'=>'Eksport recenzji do pliku CSV','A utility to export reviews and replies to a CSV file. Use the Export button to start export of reviews. Use the Download button to download the last export.'=>'Narzędzie do eksportowania recenzji do pliku CSV. Użyj przycisku Eksportuj, aby rozpocząć eksport recenzji. Użyj przycisku Pobierz, aby pobrać ostatni eksport.','Failed to download: invalid nonce. <a href="%s">Return to settings</a>'=>'Nie udało się pobrać: nieprawidłowy numer jednorazowy. <a href="%s">Wróć do ustawień</a>','Export Completed'=>'Eksport zakończony','Export is in progress'=>'Trwa eksport','Export'=>'Eksport','Line %1$d >> Error: order_id must be a positive number or empty.'=>'Wiersz %1$d >> Błąd: order_id musi być liczbą dodatnią lub być pusty.','Import / Export'=>'Import / Eksport','CR: a review reminder was not scheduled due to a bespoke filter.'=>'CR: przypomnienie o recenzji nie zostało zaplanowane z powodu niestandardowego filtra.','German (Formal)'=>'Niemiecki (formalny)','Icelandic'=>'islandzki','Sorry, no reviews match your current selections'=>'Przepraszamy, żadne recenzje nie pasują do twoich aktualnych wyborów','Search'=>'Szukaj','Search customer reviews'=>'Wyszukaj recenzje klientów','Shortcode and preview of the compact dark trust badge.'=>'Shortcode i podgląd kompaktowej ciemnej odznaki zaufania.','Compact Dark Badge'=>'Kompaktowa ciemna odznaka','Shortcode and preview of the compact light trust badge.'=>'Shortcode i podgląd kompaktowej jasnej odznaki zaufania.','Compact Light Badge'=>'Kompaktowa jasna odznaka','Bottom left'=>'Na dole po lewej','Bottom right'=>'Na dole po prawej','Choose one of the locations for the floating trust badge.'=>'Wybierz jedną z lokalizacji dla pływającej odznaki zaufania.','Floating Badge Location'=>'Lokalizacja pływającej odznaki','Replace the standard ‘verified owner’ label that WooCommerce adds to customer reviews with a custom one. If this field is blank, the standard WooCommerce label will be used.'=>'Zamień standardową etykietę "zweryfikowany właściciel", którą WooCommerce dodaje do recenzji klientów na niestandardową. Jeśli to pole jest puste, standardowa etykieta WooCommerce zostanie użyta.','Choose one of the styles for the floating trust badge.'=>'Wybierz jeden ze stylów dla pływającej odznaki zaufania.','Floating Badge Style'=>'Styl pływającej odznaki','Enable this checkbox to display a floating trust badge on public pages of the website.'=>'Włącz to pole wyboru, aby wyświetlać pływającą odznakę zaufania na publicznych stronach witryny.','Floating Badge'=>'Pływająca odznaka','Settings to display a floating badge with a summary of verified reviews.'=>'Ustawienia wyświetlania pływającej odznaki z podsumowaniem zweryfikowanych recenzji.','Floating Trust Badge'=>'Pływająca odznaka zaufania','Error: cURL library is missing on the server.'=>'Błąd: na serwerze brakuje biblioteki cURL.','\'Email Body\' field cannot be empty'=>'Pole "Treść wiadomości e-mail" nie może być puste','Error: the customer has unsubscribed from emails.'=>'Błąd: klient wypisał się z e-maili.','N/A'=>'Brak danych','A prefix that will be added to coupon codes generated by the plugin.'=>'Prefiks, który zostanie dodany do kodów kuponów generowanych przez wtyczkę.','Coupon prefix'=>'Prefiks kuponu','Add product identifiers to structured data markup on WooCommerce product pages. According to Google\'s requirements, product identifiers will also be added to the HTML shown to visitors.'=>'Dodaj identyfikatory produktów do znaczników danych strukturalnych na stronach produktów WooCommerce. Zgodnie z wymaganiami Google, identyfikatory produktów zostaną również dodane do kodu HTML wyświetlanego odwiedzającym.','Structured Data'=>'Dane strukturalne','Google might reject XML feeds with very short reviews. Use this setting to specify a minimum number of characters that a review should have to be included in the XML feed.'=>'Google może odrzucać kanały XML z bardzo krótkimi recenzjami. Użyj tego ustawienia, aby określić minimalną liczbę znaków, które recenzja powinna mieć, aby była zawarta w pliku XML.','Minimum Length of Reviews'=>'Minimalna długość recenzji','Customer Images'=>'Obrazy klientów','Text of the message shown to customers next to the consent checkbox on the checkout page.'=>'Tekst wiadomości wyświetlanej klientom obok pola wyboru zgody na stronie zamówienia.','Customer Consent Text'=>'Tekst zgody klienta','Enable this option if you would like to make it mandatory for your customers to write something in their review. This option applies only to aggregated review forms.'=>'Zaznacz tą opcję, jeśli chcesz, aby klienci musieli napisać coś w swojej recenzji. Opcja ta dotyczy tylko zagregowanych formularzy recenzji.','Most helpful reviews first'=>'Najpierw najbardziej pomocne recenzje','Recent reviews first'=>'Najpierw najnowsze recenzje','Define how reviews are sorted by default. The option to vote for reviews must be enabled to show the most helpful reviews first.'=>'Zdefiniuj domyślny sposób sortowania recenzji. Aby w pierwszej kolejności były wyświetlane najbardziej przydatne recenzje, należy włączyć opcję głosowania na recenzje.','Default Sorting Order'=>'Domyślna kolejność sortowania','Specify the default number of reviews that will be shown during the initial product page load.'=>'Określ domyślną liczbę recenzji, które będą wyświetlane podczas początkowego ładowania strony produktu.','Default Quantity of Reviews'=>'Domyślna liczba recenzji','Show more'=>'Pokaż więcej','Most Helpful'=>'Najbardziej pomocne','Most Recent'=>'Najnowsze','Georgian'=>'Gruziński','Error: reminders are disabled for guests.'=>'Błąd: przypomnienia dla gości są wyłączone.','Enable sending of review reminders to customers who place orders without an account (guest checkout). It is recommended to enable this checkbox, if you allow customers to place orders without creating an account on your site.'=>'Włącz wysyłanie przypomnień o recenzjach do klientów, którzy składają zamówienia bez konta. Zaleca się zaznaczenie tego pola wyboru, jeśli pozwalasz klientom składać zamówienia bez zakładania konta w twojej witrynie.','Enable for Guests'=>'Włącz dla gości','Adjust template of the aggregated review forms that will be created and sent to customers by CusRev. Modifications will be applied to the next review form created after saving settings. If you enable <b>advanced</b> form templates in your account on %1$sCusRev website%2$s, they will <b>override</b> the settings below.'=>'Dostosuj szablon zagregowanych formularzy recenzji, które będą tworzone i wysyłane do klientów przez CusRev. Modyfikacje zostaną zastosowane do następnego formularza recenzji utworzonego po zapisaniu ustawień. Jeśli włączysz <b>zaawansowane</b> szablony formularzy na swoim koncie na stronie %1$sCusRev%2$s, będą one <b>nadpisywać</b> poniższe ustawienia.','Enable manual sending of follow-up emails with a reminder to submit a review. Manual reminders can be sent for completed orders from %1$sOrders%2$s page after enabling this option.'=>'Włącz ręczne wysyłanie wiadomości e-mail z przypomnieniem o konieczności przesłania recenzji. Ręczne przypomnienia mogą być wysyłane dla zrealizowanych zamówień ze strony %1$sZamówienia%2$s po włączeniu tej opcji.','Enable this option to track orders placed by customers who were referred to your store from %1$scusrev.com%2$s. Tracking is implemented via a 30-day cookie created by the plugin for customers who are referred to your store.'=>'Włącz tę opcję, aby śledzić zamówienia złożone przez klientów, którzy zostali skierowani do twojego sklepu z %1$scusrev.com%2$s. Śledzenie jest realizowane za pomocą 30-dniowego pliku cookie utworzonego przez wtyczkę dla klientów, którzy są kierowani do twojego sklepu.','Track Customer Referrals'=>'Śledź poleconych klientów','Tracking of referrals requires: (1) %1$sTrust Badges%2$s option has to be enabled, (2) a valid %3$slicense key%4$s (Free or Pro) has to be provided.'=>'Śledzenie osób poleconych wymaga: (1) musi być włączona opcja %1$sOdznaki zaufania%2$s, (2) musi być podany ważny %3$sKlucz licencji%4$s (Free lub Pro).','Referral marketing is one of the most cost-effective ways to acquire new customers. It is based on the idea that your current customers will spread the word about your store and bring in (or refer) new customers. The problem is that it is not easy for them to do so. We help your customers to spread the word by showing their public reviews to other customers at %1$scusrev.com%2$s.'=>'Marketing polecający jest jednym z najbardziej opłacalnych sposobów pozyskiwania nowych klientów. Opiera się na założeniu, że twoi obecni klienci będą rozpowszechniać informacje o twoim sklepie i przyciągać (lub polecać) nowych klientów. Problem w tym, że nie jest to dla nich łatwe. Pomagamy twoim klientom rozpowszechniać informacje, pokazując ich publiczne recenzje innym klientom %1$scusrev.com%2$s.','Referral Program'=>'Program polecający','Displays whether or not XMLWriter extension is enabled. This extension is required to generate XML feeds with products and reviews. If the extension is disabled, please reach out to your hosting support and ask them to enable it.'=>'Wyświetla, czy rozszerzenie XMLWriter jest włączone czy nie. To rozszerzenie jest wymagane do generowania feedów XML z produktami i recenzjami. Jeśli rozszerzenie jest wyłączone, skontaktuj się z obsługą swojego hostingu i poproś o jego włączenie.','XMLWriter:'=>'XMLWriter:','https://www.cusrev.com/business/'=>'https://www.cusrev.com/business/','MPN: '=>'MPN: ','An overview of features available in the Free and Pro versions of Customer Reviews: %s'=>'Przegląd funkcji dostępnych w wersjach Free i Pro wtyczki Customer Reviews: %s','Product Tag'=>'Tag produktu','If you sell variable products, enable this option to include product variations in the XML product feed.'=>'Jeśli sprzedajesz produkty z wariantami, włącz tę opcję, aby uwzględnić warianty produktów w pliku danych produktowych XML.','Include product variants in the XML product feed'=>'Uwzględnij warianty produktów w pliku danych produktowych XML','Product Variants'=>'Warianty produktu','Enable the option to add "identifier_exists = no" in Google Shopping feed for this variation.'=>'Włącz opcję dodawania "identifier_exists = no" w pliku danych Zakupów Google (Google Shopping) dla tego wariantu..','Enable the checkbox to add "identifier_exists = no" in Google Shopping feed for this product.'=>'Włącz pole wyboru, aby dodać "identifier_exists = no" w pliku danych Zakupów Google (Google Shopping) dla tego produktu.','identifier_exists attribute for Google Shopping'=>'atrybut identifier_exists dla Zakupów Google (Google Shopping)','Add an identifier_exists field to WooCommerce products (on \'Inventory\' tab). Use it to indicate whether or not the unique product identifiers and brand are available for a product.'=>'Dodaj pole identifier_exists do produktów WooCommerce (na karcie „Magazyn”). Użyj go, aby wskazać, czy unikatowe identyfikatory produktów i marka są dostępne dla produktu, czy nie.','identifier_exists'=>'identifier_exists','URL of the file with the product feed that should be maintained in Google Merchant Center.'=>'URL pliku XML danych produktowych, który powinien być przechowywany w Google Merchant Center.','Google Shopping is a service that allows merchants to list their products by uploading a product feed in the <a href="https://merchants.google.com/">Merchant Center</a>. Use XML Product Review Feed to enable star ratings for your products in Google Shopping.'=>'Zakupy Google (Google Shopping) to usługa, która umożliwia sprzedawcom wyświetlanie listy produktów przez przesłanie pliku danych produktów do <a href="https://merchants.google.com/">Merchant Center</a>. Użyj pliku XML z recenzjami produktów, aby włączyć ocenianie produktów w gwiazdkach w Zakupach Google.','Reviews XML Feed'=>'Plik XML z recenzjami','WooCommerce product fields should be mapped to Google product identifiers on "Reviews" tab.'=>'Pola produktów WooCommerce powinny być mapowane do identyfikatorów produktów Google w zakładce "Recenzje".','<strong>%1d / %2d</strong> product identifiers (reviews) mapped'=>'<strong>%1d / %2d</strong> identyfikatorów produktów (recenzji) zmapowanych','WooCommerce product fields should be mapped to Google product identifiers on "Product Identifiers" tab.'=>'Pola produktów WooCommerce powinny zostać zmapowane do identyfikatorów produktów Google w zakładce "Identyfikatory produktów".','<strong>%1d / %2d</strong> product identifiers mapped'=>'<strong>%1d / %2d</strong> identyfikatorów produktów zmapowanych','WooCommerce product categories should be mapped to Google categories on "Categories" tab.'=>'Kategorie produktów WooCommerce powinny być zmapowane do kategorii Google w zakładce "Kategorie".','<strong>%1d / %2d</strong> product categories mapped, <strong>%3d</strong> excluded'=>'<strong>%1d / %2d</strong> kategorie produktów zmapowane, <strong>%3d</strong> nie dotyczy','Information about the product categories and product identifiers.'=>'Informacje o kategoriach produktów i identyfikatorach produktów.','Status'=>'Status','Product Review Feed URL'=>'Adres URL pliku z recenzjami produktów','Product Feed URL'=>'Adres URL pliku danych produktów','Generate XML Product Feed'=>'Wygeneruj plik danych produktowych XML','Overview'=>'Przegląd','WP Cron error'=>'Błąd WP Cron','Brand: '=>'Marka: ','GTIN: '=>'GTIN: ','No product categories found'=>'Nie znaleziono kategorii produktów','Product category from Google Shopping product taxonomy'=>'Kategoria produktu z taksonomii produktu Google Shopping','Google Shopping Category'=>'Kategoria Google Shopping','Exclude a category of products from the Product Feed'=>'Wyklucz kategorię produktów z pliku danych produktów','Exclude'=>'Wyklucz','Number of products in a category'=>'Liczba produktów w kategorii','Product Count'=>'Ilość produktów','Product category in WooCommerce'=>'Kategoria produktów w WooCommerce','Product Category'=>'Kategoria produktu','Specify mapping of WooCommerce product categories to Google Shopping product categories. The full list of Google Shopping product categories can be found %shere'=>'Określ mapowanie kategorii produktów WooCommerce do kategorii produktów Google Shopping. Pełna lista kategorii produktów Google Shopping znajduje się %stutaj','The brand of the product.'=>'Marka produktu.','MPN refers to a Manufacturer Part Number, a number that uniquely identifies the product to its manufacturer.'=>'MPN oznacza Manufacturer Part Number, czyli numer, który jednoznacznie identyfikuje produkt z jego producentem.','Manufacturer Part Number'=>'Manufacturer Part Number','GTIN refers to a Global Trade Item Number, a globally unique number used to identify trade items, products, or services that can be purchased. GTIN is also an umbrella term that refers to UPC, EAN, JAN, and ISBN.'=>'GTIN oznacza Globalny Numer Jednostki Handlowej (Global Trade Item Number), globalnie unikalny numer używany do identyfikacji przedmiotów handlu, produktów lub usług, które mogą być zakupione. GTIN jest również terminem zbiorczym, który odnosi się do UPC, EAN, JAN i ISBN.','Global Trade Item Number'=>'Global Trade Item Number','Product Brand'=>'Marka produktu','Product MPN'=>'MPN produktu','Product GTIN'=>'GTIN produktu','Product identifiers required by Google Shopping'=>'Identyfikatory produktów wymagane przez Google Shopping','Google Shopping Identifier'=>'Identyfikator Google Shopping','Select a product field that should be mapped'=>'Wybierz pole produktu, które ma zostać zmapowane','WooCommerce Product Field'=>'Pole produktu WooCommerce','Add an MPN field to WooCommerce products (on \'Inventory\' tab). MPN refers to a Manufacturer Part Number, a number that uniquely identifies the product to its manufacturer.'=>'Dodaj pole MPN do produktów WooCommerce (na karcie „Magazyn”). MPN odnosi się do Manufacturer Part Number, numeru, który jednoznacznie identyfikuje produkt z jego producentem.','Add a GTIN field to WooCommerce products (on \'Inventory\' tab). GTIN refers to a Global Trade Item Number, a globally unique number used to identify trade items, products, or services that can be purchased. GTIN is also an umbrella term that refers to UPC, EAN, JAN, and ISBN.'=>'Dodaj pole GTIN do produktów WooCommerce (na karcie „Magazyn”). GTIN odnosi się do Global Trade Item Number, globalnie unikatowego numeru używanego do identyfikacji przedmiotów handlowych, produktów lub usług, które można kupić. GTIN jest również terminem zbiorczym, który odnosi się do UPC, EAN, JAN i ISBN.',' Enable additional fields to maintain product identifiers in WooCommerce products. Next, specify mapping of WooCommerce product fields to Google Shopping product identifiers.'=>'Włącz dodatkowe pola, aby zachować identyfikatory produktów w produktach WooCommerce. Następnie określ mapowanie pól produktów WooCommerce do identyfikatorów produktów Google Shopping.','Product Identifiers'=>'Identyfikatory produktów','Ukrainian'=>'ukraiński','Portuguese (Brazil)'=>'portugalski (Brazylia)','Persian'=>'perski','This warning can be safely ignored, if your theme does not use the offical WooCommerce libraries.'=>'To ostrzeżenie może być bezpiecznie zignorowane, jeśli twój motyw nie używa oficjalnych bibliotek WooCommerce.','Specify a default brand for all products in your store. If this field is non-empty, the plugin will use this brand for all products in XML feeds for Google Shopping.'=>'Określ domyślną markę dla wszystkich produktów w twoim sklepie. Jeśli to pole nie jest puste, wtyczka użyje tej marki dla wszystkich produktów w pliku XML produktów dla Google Shopping.','Brand (Static)'=>'Marka (statyczna)','You must be %1$slogged in%2$s to post a review.'=>'Musisz się %1$szalogować%2$s, aby dodać opinię.','CR Cron'=>'CR Cron','WordPress Cron'=>'WordPress Cron','Define which scheduler the plugin will use to schedule automatic review reminders. The default option is to use WordPress Cron (WP-Cron) for scheduling automatic reminders. If your hosting limits WordPress Cron functionality and automatic reminders are not sent as expected, try CR Cron. CR Cron is an external service that requires a license key (free or pro).'=>'Określ, którego harmonogramu wtyczka użyje do zaplanowania automatycznych przypomnień o przeglądach. Domyślną opcją jest użycie WordPress Cron (WP-Cron) do zaplanowania automatycznych przypomnień. Jeśli twój hosting ogranicza funkcjonalność WordPress Cron, a automatyczne przypomnienia nie są wysyłane zgodnie z oczekiwaniami, spróbuj CR Cron. CR Cron to usługa zewnętrzna, która wymaga klucza licencyjnego (darmowego lub pro).','Reminders Scheduler'=>'Harmonogram przypomnień','Error: the customer has already reviewed all products from this order.'=>'Błąd: klient ocenił już wszystkie produkty z tego zamówienia.','%d reminder sent'=>'Wysłano %d przypomnienie' . "\0" . 'Wysłano %d przypomnienia' . "\0" . 'Wysłano %d przypomnień','No customer consent received'=>'Nie otrzymano zgody klienta','A review reminder was scheduled via CR Cron'=>'Przypomnienie o recenzji zostało zaplanowane przez CR Cron','Error: the customer\'s email is invalid.'=>'Błąd: adres e-mail klienta jest nieprawidłowy.','Successfully synced with CR Cron'=>'Pomyślna synchronizacja z CR Cron','Sync the order with CR Cron'=>'Zsynchronizuj zamówienie z CR Cron','CR: a review reminder could not be scheduled via CR Cron. Error %d.'=>'CR: nie można zaplanować przypomnienia o recenzji za pomocą CR Cron. Błąd %d.','CR: a review reminder was scheduled via CR Cron. Please log in to your account on <a href="https://www.cusrev.com/login.html" target="_blank" rel="noopener noreferrer">CR website</a> to view and manage the reminders.'=>'CR: Zaplanowano przypomnienie o recenzji za pośrednictwem CR Cron. Proszę zalogować się na swoje konto na <a href="https://www.cusrev.com/login.html" target="_blank" rel="noopener noreferrer">stronie CR</a> aby zobaczyć i zarządzać przypomnieniami.','<strong>CR Cron could not be enabled because no license key was entered. A license key (free or pro) is required to use CR Cron.</strong>'=>'<strong>CR Cron nie mógł zostać włączony, ponieważ nie wprowadzono klucza licencyjnego. Do korzystania z CR Cron wymagany jest klucz licencyjny (free lub pro).</strong>','If this option is enabled, customers will be asked to tick a checkbox on the checkout page to indicate that they would like to receive an invitation to review their order.'=>'Jeśli ta opcja jest włączona, klienci będą proszeni o zaznaczenie pola wyboru na stronie zamówienia, aby wskazać, że chcieliby otrzymać zaproszenie do recenzji swojego zamówienia.','Customer Consent'=>'Zgoda klienta','Store manager'=>'Kierownik sklepu','Your review is awaiting approval'=>'Twój komentarz czeka na moderację','Answers to Custom Questions'=>'Odpowiedzi na spersonalizowane pytania','Specify an email to receive notifications about new reviews and errors. It is recommended to provide an email address that you regularly check.'=>'Określ adres e-mail, na który chcesz otrzymywać powiadomienia o nowych recenzjach i błędach. Zalecane jest podanie adresu e-mail, który regularnie sprawdzasz.','Email for Notifications'=>'E-mail do powiadomień','Croatian'=>'chorwacki','Slovak'=>'słowacki','Line %1$d >> Error: product_id must be a positive number or \'-1\' for shop reviews.'=>'Wiersz %1$d >> Błąd: product_id musi być liczbą dodatnią lub \'-1\' dla recenzji sklepu.','Doe'=>'Kowalski','\'Form Body\' field cannot be empty'=>'Pole „Treść formularza” nie może być puste','\'Form Header\' field cannot be empty'=>'Pole „Nagłówek formularza” nie może być puste','View additional information'=>'Wyświetl dodatkowe informacje','Error: only one review invitation per order is allowed.'=>'Błąd: dozwolone jest tylko jedno zaproszenie do recenzji na zamówienie.','Expired: Professional Version'=>'Wygasła: Wersja profesjonalna','The plugin is based on the standard WooCommerce reviews functionality. Here, you can configure various extensions for standard WooCommerce reviews.'=>'Wtyczka jest oparta na standardowej funkcjonalności recenzji WooCommerce. Tutaj możesz skonfigurować różne rozszerzenia dla standardowych recenzji WooCommerce.','Color of control elements (buttons, rating bars).'=>'Kolor elementów sterujących (przyciski, paski oceny).','Form Color 3'=>'Kolor formularza 3','Automatic geolocation on review forms.'=>'Automatyczna geolokalizacja na formularzach recenzji.','Enable geolocation on aggregated review forms. Customers will have an option to indicate where they are from. For example, "England, United Kingdom".'=>'Włącz geolokalizację na zagregowanych formularzach recenzji. Klienci będą mieli możliwość wskazania miejsca, z którego pochodzą. Na przykład: "Anglia, Wielka Brytania".','Geolocation'=>'Geolokalizacja','Stars'=>'Gwiazdki','Smiley and frowny faces'=>'Uśmiechnięte i smutne twarze','Visual style of rating bars on review forms.'=>'Styl wizualny pasków oceny na formularzach recenzji.','Rating Bar'=>'Pasek oceny','Active: Professional Version'=>'Aktywna: Wersja profesjonalna','Types of License Keys'=>'Rodzaje kluczy licencyjnych','Latvian'=>'łotewski','Add a Reply-To address for emails with reminders. If customers decide to reply to automatic emails, their replies will be sent to this address. It is recommended to use an email address associated with the domain of your site. If you use a free email address (e.g., Gmail or Hotmail), it will increase probability of emails being marked as SPAM.'=>'Dodaj adres Reply-To dla e-maili z przypomnieniami. Jeśli klienci zdecydują się odpowiedzieć na automatyczne e-maile, ich odpowiedzi będą wysyłane na ten adres. Zalecane jest użycie adresu e-mail powiązanego z domeną twojej witryny. Jeśli użyjesz darmowego adresu e-mail (np. Gmail lub Hotmail), zwiększy to prawdopodobieństwo, że e-maile zostaną oznaczone jako SPAM.','Macedonian'=>'macedoński','Greek'=>'grecki','A reminder is scheduled for '=>'Przypomnienie zaplanowano na ','%d review received'=>'Otrzymano %d recenzję' . "\0" . 'Otrzymano %d recenzje' . "\0" . 'Otrzymano %d recenzji','A verified copy of this reply was published on %1$s. If this reply is deleted, the verified copy will remain published. The page with verified copies of reviews and replies to reviews for your shop on CusRev portal can be completely hidden by disabling Trust Badges in the %2$s.'=>'Zweryfikowana kopia tej odpowiedzi została opublikowana na stronie %1$s. Jeśli odpowiedź zostanie usunięta, zweryfikowana kopia pozostanie opublikowana. Strona ze zweryfikowanymi kopiami recenzji i odpowiedzi na recenzje dla twojego sklepu w portalu CusRev może zostać całkowicie ukryta poprzez wyłączenie odznak zaufania w %2$s.','This reply was originally posted on %1$s. If this copy of the reply is deleted, the original on CusRev portal will remain published. If this copy is edited, the original reply will NOT be updated. Only the customer can edit the original reply on CusRev portal. The page with verified copies of reviews and replies to reviews for your shop on CusRev portal can be completely hidden by disabling Trust Badges in the %2$s.'=>'Ta odpowiedź została pierwotnie zamieszczona na stronie %1$s. Jeśli kopia odpowiedzi zostanie usunięta, oryginał na portalu CusRev pozostanie opublikowany. Jeśli kopia zostanie edytowana, oryginalna odpowiedź NIE zostanie zaktualizowana. Tylko klient może edytować oryginalną odpowiedź na portalu CusRev. Strona ze zweryfikowanymi kopiami recenzji i odpowiedzi na recenzje dla twojego sklepu w portalu CusRev może zostać całkowicie ukryta poprzez wyłączenie odznak zaufania w %2$s.','A verified copy of this reply was published on %s'=>'Zweryfikowana kopia tej odpowiedzi została opublikowana na stronie %s','A verified copy of this reply was published on %1$s. If this reply is deleted, the verified copy will remain published. If this reply is edited, the verified copy will be updated. The page with verified copies of reviews and replies to reviews for your shop on CusRev portal can be completely hidden by disabling Trust Badges in the %2$s.'=>'Zweryfikowana kopia tej odpowiedzi została opublikowana na stronie %1$s. Jeśli odpowiedź zostanie usunięta, zweryfikowana kopia pozostanie opublikowana. Jeśli odpowiedź jest edytowana, zweryfikowana kopia zostanie zaktualizowana. Strona ze zweryfikowanymi kopiami recenzji i odpowiedzi na recenzje dla twojego sklepu w portalu CusRev może zostać całkowicie ukryta poprzez wyłączenie odznak zaufania w %2$s.','This reply was originally posted on CusRev portal. This copy of the reply was modified and might be different from the original reply published on CusRev portal.'=>'Odpowiedź została pierwotnie zamieszczona na portalu CusRev. Niniejsza kopia odpowiedzi została zmodyfikowana i może różnić się od oryginalnej odpowiedzi opublikowanej na portalu CusRev.','A verified copy published on %s could not be updated because it is not the last reply for the review. The verified copy might be different from this reply.'=>'Zweryfikowana kopia opublikowana w dniu %s nie mogła zostać zaktualizowana, ponieważ nie jest to ostatnia odpowiedź dla tej recenzji. Zweryfikowana kopia może być inna niż ta odpowiedź.','A copy of this reply will not be published on %1$s because no license key was entered in the %2$s. A license key (free or professional) is used as a secret token for additional security when communicating with CusRev service.'=>'Kopia tej odpowiedzi nie zostanie opublikowana na stronie %1$s, ponieważ w polu %2$s nie został wpisany klucz licencyjny. Klucz licencyjny (darmowy lub profesjonalny) jest używany jako tajny token zapewniający dodatkowe bezpieczeństwo podczas komunikacji z usługą CusRev.','plugin\'s settings'=>'ustawienia wtyczki','CusRev (Customer Reviews) portal'=>'Portal CusRev (Customer Reviews)','This reply was originally posted on CR portal'=>'Ta odpowiedź została pierwotnie zamieszczona na portalu CR','Error: the order does not contain any products for which review reminders are enabled in the settings.'=>'Błąd: zamówienie nie zawiera żadnych produktów, dla których w ustawieniach włączone są przypomnienia o recenzji.','Enable this checkbox to exclude free products from review invitations.'=>'Zaznacz to pole wyboru, aby wykluczyć darmowe produkty z zaproszeń do recenzji.','Exclude Free Products'=>'Wyklucz bezpłatne produkty','Rating'=>'Ocena','Product Categories'=>'Kategorie produktów','Dark'=>'Ciemny','Light'=>'Jasny','%s = human-readable time difference%s ago'=>'%s temu','Verified Owner'=>'Zweryfikowany właściciel','No reviews to show'=>'Brak recenzji do wyświetlenia','ID of the current user is not set'=>'Identyfikator bieżącego użytkownika nie jest ustawiony','Unknown error'=>'Nieznany błąd','A copy of this reply was published on CusRev portal'=>'Kopia tej odpowiedzi została opublikowana na portalu CusRev','Error: could not save the secret key to DB. Please try again.'=>'Błąd: nie można zapisać tajnego klucza do bazy danych. Proszę spróbować ponownie.','Search Reminders'=>'Wyszukaj przypomnienia','Customer Reviews (CR)'=>'Customer Reviews (CR)','Review reminders will be sent N days after this order status. It is recommended to use \'Completed\' status.'=>'Przypomnienia o recenzji będą wysyłane N dni po tym statusie zamówienia. Zalecane jest używanie statusu \'Zrealizowane\'.','Order Status'=>'Status zamówienia','Active: Free Version'=>'Aktywna: Wersja darmowa','comments%s in moderation'=>'%s w moderacji' . "\0" . '%s w moderacji' . "\0" . '%s w moderacji','%s Comment'=>'%s komentarz' . "\0" . '%s komentarze' . "\0" . '%s komentarzy','ERROR: please type a comment.'=>'BŁĄD: Proszę wpisać komentarz.','Sorry, you must be logged in to reply to a comment.'=>'Przepraszamy, musisz się zalogować, aby móc odpowiadać na komentarze.','ERROR: you are replying to a comment on a draft post.'=>'BŁĄD: Nie można odpowiadać na komentarze do szkiców wpisów.','Submit Reply'=>'Wyślij odpowiedź','Update Comment'=>'Zaktualizuj komentarz','Add Comment'=>'Dodaj komentarz','URL'=>'Adres URL','Comment'=>'Komentarz','Add new Comment'=>'Dodaj nowy komentarz','Reply to Review'=>'Odpowiedz na recenzję','Edit Comment'=>'Edytuj komentarz','Please enter your license key (free or pro) in the field below. The plugin will automatically determine type of your license key.'=>'Proszę wpisać swój klucz licencyjny (free lub pro) w poniższym polu. Wtyczka automatycznie określi typ twojego klucza licencyjnego.','Reply'=>'Odpowiedz','Reply to this comment'=>'Odpowiedz na ten komentarz','No reviews found.'=>'Nie znaleziono recenzji.','CR: a review reminder was successfully scheduled for %s.'=>'CR: przypomnienie o recenzji zostało pomyślnie zaplanowane dla %s.','CR: a review reminder could not be scheduled.'=>'CR: nie można zaplanować przypomnienia o recenzji.','Order Number'=>'Numer zamówienia','Select reminder'=>'Wybierz przypomnienie','Actions'=>'Działania','Scheduled'=>'Zaplanowano','Order'=>'Zamówienie','Send Now'=>'Wyślij teraz','There are currently no scheduled review reminders'=>'Obecnie nie ma zaplanowanych przypomnień o recenzjach','Are you sure you want to send the review reminder(s) now?'=>'Czy na pewno chcesz teraz wysłać przypomnienie(a) o recenzji?','Are you sure you want to cancel the review reminder(s)?'=>'Czy na pewno chcesz anulować przypomnienie(a) o recenzji?','Scheduled Review Reminders'=>'Zaplanowane przypomnienia o recenzjach','Reminders'=>'Przypomnienia','Error: You tried to upload too many files. The maximum number of files that can be uploaded is %d.'=>'Błąd: Próbowałeś przesłać zbyt wiele plików. Maksymalna liczba plików, które mogą być przesłane to %d.','XML Feed Field'=>'Pole pliku danych XML','Specify WooCommerce fields that should be mapped to GTIN, MPN, SKU, and Brand fields in XML Product Review Feed for Google Shopping.'=>'Określ pola WooCommerce, które powinny być mapowane do pól GTIN, MPN, SKU i Brand (Marka) w pliku produktowym XML dla Google Shopping.','Fields Mapping'=>'Mapowanie pól','Enable attachment of pictures and videos on aggregated review forms. Uploaded media files are initially stored on Amazon S3 and automatically downloaded into WordPress Media Library later. This option applies only to aggregated review forms. If you would like to enable attachment of pictures to reviews submitted on WooCommerce product pages, please do it in the settings for on-site review forms.'=>'Włącz dołączanie zdjęć i filmów w formularzach recenzji agregowanych. Przesłane pliki multimedialne są początkowo przechowywane w Amazon S3 i automatycznie pobierane do multimediów WordPress później. Ta opcja dotyczy tylko formularzy recenzji agregowanych. Jeśli chcesz włączyć dołączanie zdjęć do recenzji przesłanych na stronach produktów WooCommerce, zrób to w ustawieniach formularzy recenzji na stronie.','Vietnamese'=>'wietnamski',' Error message: '=>'Treść błędu:','Details: '=>'Szczegóły: ','Error message: '=>'Treść błędu: ','Error code: '=>'Kod błędu: ','Enable this option to remove plugin\'s branding ("Powered by Customer Reviews plugin") from the reviews summary bar. If you like our plugin and would like to support us, please disable this checkbox.'=>'Włącz tę opcję, aby usunąć branding wtyczki ("Powered by Customer Reviews plugin") z paska podsumowania recenzji. Jeśli podoba ci się nasza wtyczka i chcesz nas wesprzeć, wyłącz to pole wyboru.','Product Name'=>'Nazwa produktu','Product SKU'=>'SKU produktu','Product ID'=>'Identyfikator produktu','Brand'=>'Marka','SKU'=>'SKU','MPN'=>'MPN','GTIN'=>'GTIN','WooCommerce Field'=>'Pole WooCommerce','URL of the file with the product reviews feed that should be maintained in Google Merchant Center.'=>'Adres URL pliku z recenzjami produktów, który powinien być przechowywany w Google Merchant Center.','Generate XML Product Review Feed for Google Shopping'=>'Generowanie danych XML recenzji produktów dla Zakupów Google (Google Shopping)','Integration with Google Services'=>'Integracja z usługami Google','Google'=>'Google','Anonymous'=>'Anonim','Lithuanian'=>'litewski','Line %1$d >> Error: no data for this review.'=>'Wiersz %1$d >> Błąd: brak danych dla tej recenzji.','Live mode activation error: page URL contains unsupported symbols. Only latin characters (a-z), numbers (0-9), and . symbol are allowed.'=>'Błąd aktywacji trybu Live: adres URL strony zawiera nieobsługiwane symbole. Dozwolone są tylko znaki łacińskie (a-z), cyfry (0-9) oraz kropka.','Shortcode and preview of the wide dark trust badge with store rating. The wide badge has a version for small screens that will be automatically shown when a website is viewed from phones.'=>'Shortcode i podgląd szerokiej ciemnej odznaki zaufania z oceną sklepu. Szeroka odznaka posiada wersję dla małych ekranów, która będzie automatycznie wyświetlana, gdy strona jest oglądana z telefonów.','Wide Dark Badge (with Store Rating)'=>'Szeroka ciemna odznaka (z oceną sklepu)','Shortcode and preview of the wide dark trust badge. The wide badge has a version for small screens that will be automatically shown when a website is viewed from phones.'=>'Shortcode i podgląd szerokiej ciemnej odznaki zaufania. Szeroka odznaka ma wersję dla małych ekranów, która będzie automatycznie wyświetlana, gdy strona jest przeglądana z telefonów.','Wide Dark Badge'=>'Szeroka ciemna odznaka','Shortcode and preview of the wide light trust badge with store rating. The wide badge has a version for small screens that will be automatically shown when a website is viewed from phones.'=>'Shortcode i podgląd szerokiej jasnej odznaki zaufania z oceną sklepu. Szeroka odznaka ma wersję dla małych ekranów, która będzie automatycznie wyświetlana, gdy strona jest przeglądana z telefonów.','Wide Light Badge (with Store Rating)'=>'Szeroka jasna odznaka (z oceną sklepu)','Shortcode and preview of the wide light trust badge. The wide badge has a version for small screens that will be automatically shown when a website is viewed from phones.'=>'Shortcode i podgląd szerokiej jasnej odznaki. Szeroka odznaka ma wersję dla małych ekranów, która będzie automatycznie wyświetlana, gdy strona jest przeglądana z telefonów.','Wide Light Badge'=>'Szeroka jasna odznaka','Shortcode and preview of the small dark trust badge with store rating.'=>'Shortcode i podgląd małej ciemnej odznaki zaufania z oceną sklepu.','Small Dark Badge (with Store Rating)'=>'Mała ciemna odznaka (z oceną sklepu)','Shortcode and preview of the small dark trust badge.'=>'Shortcode i podgląd małej ciemnej odznaki zaufania.','Small Dark Badge'=>'Mała ciemna odznaka','Shortcode and preview of the small light trust badge with store rating.'=>'Shortcode i podgląd małej jasnej odznaki zaufania z oceną sklepu.','Small Light Badge (with Store Rating)'=>'Mała jasna odznaka (z oceną sklepu)','Shortcode and preview of the small light trust badge.'=>'Shortcode i podgląd małej jasnej odznaki zaufania.','Small Light Badge'=>'Mała jasna odznaka','Trust Badges'=>'Odznaki zaufania','Attach Media'=>'Dołączanie mediów','Enable this option if you would like to include a separate question for a general shop review in addition to questions for product reviews.'=>'Zaznacz tę opcję, jeśli chcesz, aby oprócz pytań dotyczących recenzji produktów, dołączone było osobne pytanie dotyczące ogólnej recenzji sklepu.','Shop Rating'=>'Ocena sklepu','Hebrew'=>'hebrajski','Arabic'=>'arabski','External link'=>'Odnośnik zewnętrzny','Line %1$d >> Error: %2$s is not a valid email address.'=>'Wiersz %1$d >> Błąd: %2$s nie jest prawidłowym adresem e-mail.','Line %1$d >> Error: display name cannot be empty.'=>'Wiersz %1$d >> Błąd: nazwa wyświetlana nie może być pusta.','Line %1$d >> Error: product with ID = %2$d doesn\'t exist in this WooCommerce store.'=>'Wiersz %1$d >> Błąd: produkt o identyfikatorze = %2$d nie istnieje w tym sklepie WooCommerce.','<strong>Customer Reviews for WooCommerce</strong> plugin has been updated. This update adds a new feature (Shop Rating) that enables customers to rate your shop in general (website, customer service, and delivery). If you would like to try this feature, you should enable it in the <a href="%s">plugin settings</a>.'=>'Wtyczka <strong>Recenzje klientów dla WooCommerce</strong> została zaktualizowana. Ta aktualizacja dodaje nową funkcję (Oceny Sklepu), która umożliwia klientom ogólną ocenę twojego sklepu (strona internetowa, obsługa klienta i dostawa). Jeśli chcesz wypróbować tę funkcję, powinieneś włączyć ją w <a href="%s">ustawieniach wtyczki</a>.','Korean'=>'koreański','Turkish'=>'turecki','Japanese'=>'japoński','Checking license...'=>'Sprawdzanie licencji...','Enable automatic review reminders'=>'Włącz automatyczne przypomnienia o recenzjach','Hide this message (but don\'t enable automatic review reminders)'=>'Ukryj tę wiadomość (ale nie włączaj automatycznych przypomnień o recenzjach)','It looks like this site has moved or is a duplicate site. %1$sCustomer Reviews for WooCommerce%2$s has disabled sending automatic review reminder emails on this site to prevent duplicate reminders from a staging or test environment.'=>'Wygląda na to, że ta witryna została przeniesiona lub jest duplikatem witryny. %1$sCustomer Reviews for WooCommerce%2$s wyłączył wysyłanie automatycznych e-maili z przypomnieniem o recenzji na tej stronie, aby zapobiec duplikowaniu przypomnień ze środowiska produkcyjnego lub testowego.','If reminders are enabled only for specific user roles, this field enables you to choose these roles.'=>'Jeśli przypomnienia mają być włączone tylko dla określonych ról użytkowników, to pole umożliwia wybór tych ról.','Roles'=>'Role','Specific Roles'=>'Konkretne role','All Roles'=>'Wszystkie role','Define if reminders will be send for all or only specific roles of users.'=>'Określenie czy przypomnienia będą wysyłane dla wszystkich czy tylko do określonych ról użytkowników.','Enable for Roles'=>'Włącz dla ról','Disable lightboxes for images attached to reviews (not recommended). Use this option only if your theme generates lightboxes for any picture on the website and this leads to two lightboxes shown after clicking on an image attached to a review.'=>'Wyłącz lightboxy dla obrazków dołączonych do recenzji (niezalecane). Użyj tej opcji tylko jeśli twój motyw generuje lightboxy dla każdego obrazka na stronie i prowadzi to do dwóch lightboxów wyświetlanych po kliknięciu na obrazek dołączony do recenzji.','Disable Lightbox'=>'Wyłącz Lightbox','Error: the order was placed by a customer who doesn\'t have a role for which review reminders are enabled.'=>'Błąd: zamówienie zostało złożone przez klienta, który nie posiada roli, dla której włączone są przypomnienia o recenzji.','Search reviews'=>'Szukaj recenzji','This review is already marked as spam.'=>'Ta recenzja jest już oznaczona jako spam.','View Trash'=>'Zobacz zawartość kosza','This review is already in the Trash.'=>'Ta recenzja jest już w koszu.','Edit Review'=>'Edytuj recenzję','This review is already approved.'=>'Ta recenzja jest już zatwierdzona.','%s reviews deleted'=>'%s recenzja usunięta' . "\0" . '%s recenzje usunięte' . "\0" . '%s recenzji usuniętych','%s review restored from the Trash'=>'%s recenzja przywrócona z kosza' . "\0" . '%s recenzje przywrócone z kosza' . "\0" . '%s recenzji przywróconych z kosza','%s review moved to the Trash.'=>'%s recenzja przeniesiona do kosza.' . "\0" . '%s recenzji przeniesionych do kosza.' . "\0" . '%s recenzji przeniesionych do kosza.','%s review restored from the spam'=>'%s recenzja przywrócona ze spamu' . "\0" . '%s recenzji przywróconych ze spamu' . "\0" . '%s recenzji przywróconych ze spamu','Undo'=>'Cofnij','%s review marked as spam.'=>'%s recenzja oznaczona jako spam.' . "\0" . '%s recenzji oznaczonych jako spam.' . "\0" . '%s recenzji oznaczonych jako spam.','%s review approved'=>'%s recenzja zatwierdzona' . "\0" . '%s recenzji zatwierdzonych' . "\0" . '%s recenzji zatwierdzonych','Sorry, you are not allowed to edit reviews for this product.'=>'Przepraszamy, nie możesz edytować recenzji tego produktu.','Invalid Review ID.'=>'Nieprawidłowy identyfikator recenzji.','Search results for &#8220;%s&#8221;'=>'Wyniki wyszukiwania: &#8220;%s&#8221;','All Reviews'=>'Wszystkie opinie','Reviews for &#8220;%s&#8221;'=>'Recenzje dla &#8220;%s&#8221;','No pending comments'=>'Brak komentarzy oczekujących na moderację','No approved comments'=>'Brak zaakceptowanych komentarzy','No comments'=>'Brak komentarzy','%s pending comment'=>'%s oczekujący komentarz' . "\0" . '%s oczekujące komentarze' . "\0" . '%s oczekującyc